export const ОПИСАНИЯ_САМАРКАНДА: Record<string, Partial<Record<Locale, string>>> = {
  reg: {
    en: "Samarkand's main square since Timurid times, where trade roads met and decrees were proclaimed. It is framed by three madrasas: Ulugh Beg (1417–1420), Sher-Dor (17th century, its portal shows tigers carrying a sun with a human face) and Tilya-Kori (1646–1660) with a gilded mosque inside. The ensemble is part of the UNESCO site “Samarkand – Crossroad of Cultures”. Come twice: in the morning, when it is quiet, and in the evening, when the façades are lit.",
    uz: "Temuriylar davridan beri Samarqandning bosh maydoni: bu yerda savdo yoʻllari kesishgan, farmonlar oʻqilgan. Uni uchta madrasa oʻrab turadi — Ulugʻbek (1417–1420), Sherdor (XVII asr, peshtoqida inson yuzli quyoshni koʻtargan sherlar) va ichida zarhal masjidi bor Tillakori (1646–1660). Ansambl YUNESKOning «Samarqand — madaniyatlar chorrahasi» obyektiga kiradi. Ikki marta keling: odam kam boʻlgan ertalab va peshtoqlar yoritilgan kechqurun.",
    zh: "自帖木儿王朝起便是撒马尔罕的中心广场，商路在此交汇，诏令在此宣读。三座经学院环绕广场：兀鲁伯经学院（1417–1420）、希尔多尔经学院（17世纪，门楣上是驮着人面太阳的猛虎）和内有镀金清真寺的提拉-卡里经学院（1646–1660）。建筑群属于联合国教科文组织遗产“撒马尔罕——文化交汇之地”。建议来两次：清晨人少，傍晚立面亮灯。",
    ko: "티무르 시대부터 사마르칸트의 중심 광장으로, 교역로가 만나고 칙령이 낭독되던 곳입니다. 세 마드라사가 광장을 둘러쌉니다. 울루그베크(1417–1420), 셰르도르(17세기, 정문에 사람 얼굴의 태양을 등에 진 호랑이), 내부에 금박 모스크가 있는 틸랴코리(1646–1660)입니다. 유네스코 세계유산 ‘사마르칸트 – 문화의 교차로’의 일부입니다. 사람이 적은 아침과 조명이 켜지는 저녁, 두 번 오세요.",
    de: "Seit der Timuridenzeit der Hauptplatz Samarkands: Hier trafen sich Handelswege und wurden Erlasse verkündet. Drei Medresen rahmen ihn ein – Ulugh Beg (1417–1420), Scher-Dor (17. Jh., am Portal Tiger, die eine Sonne mit Menschengesicht tragen) und Tilla-Kari (1646–1660) mit vergoldeter Moschee. Das Ensemble gehört zum UNESCO-Welterbe „Samarkand – Schnittpunkt der Kulturen“. Kommen Sie zweimal: morgens, wenn es ruhig ist, und abends, wenn die Fassaden beleuchtet sind.",
    fr: "La grande place de Samarcande depuis les Timourides : les routes commerciales s'y croisaient et l'on y proclamait les décrets. Trois médersas l'encadrent : Ouloug Beg (1417–1420), Cher-Dor (XVIIe siècle, au portail des tigres portant un soleil à visage humain) et Tilla-Kari (1646–1660) avec sa mosquée dorée. L'ensemble fait partie du site UNESCO « Samarcande – carrefour de cultures ». Venez deux fois : le matin, au calme, et le soir, quand les façades s'illuminent.",
    ja: "ティムール朝以来のサマルカンドの中心広場。交易路が交わり、勅令が読み上げられた場所です。三つのメドレセが広場を囲みます。ウルグベク（1417–1420年）、シェルドル（17世紀、門には人面の太陽を背負う虎）、内部に金色のモスクがあるティラカリ（1646–1660年）。ユネスコ世界遺産「サマルカンド―文化交差路」の一部です。人の少ない朝と、ライトアップされる夜の二回訪れるのがおすすめ。",
    tr: "Timurlular döneminden beri Semerkant'ın ana meydanı: ticaret yolları burada buluşur, fermanlar burada okunurdu. Üç medrese meydanı çevreler: Uluğ Bey (1417–1420), Şirdar (17. yüzyıl, taç kapısında insan yüzlü güneşi taşıyan kaplanlar) ve içinde altın yaldızlı mescidi olan Tillakari (1646–1660). Topluluk, UNESCO'nun “Semerkant – Kültürlerin Kavşağı” alanının parçasıdır. İki kez gelin: sabah, kalabalık yokken; akşam, cepheler ışıklandırıldığında.",
    ar: "الساحة الرئيسية في سمرقند منذ العهد التيموري، حيث التقت طرق التجارة وأُعلنت المراسيم. تحيط بها ثلاث مدارس: أولوغ بيك (1417–1420)، وشير دور (القرن السابع عشر، وعلى بوابتها نمور تحمل شمساً بوجه إنسان)، وطلا كاري (1646–1660) وفيها مسجد مذهّب. المجمع جزء من موقع اليونسكو «سمرقند – ملتقى الثقافات». تعالَ مرتين: صباحاً حين يقلّ الزوار، ومساءً حين تُضاء الواجهات.",
  },
  shah: {
    en: "A street of mausoleums from the 11th–19th centuries that grew around the revered grave of Qusam ibn Abbas, the Prophet Muhammad's cousin, whom legend calls the “Living King”. Most tombs were built under the Timurids for Amir Timur's relatives and courtiers, and each has its own facing: turquoise and blue majolica, carved tiles, calligraphy. An old staircase leads up — tradition says you should count its steps going up and down. It is a place of worship, so dress modestly.",
    uz: "XI–XIX asrlarga oid maqbaralar koʻchasi. U paygʻambar Muhammadning amakivachchasi, rivoyatlarda «Tirik shoh» deb ataluvchi Qusam ibn Abbosning muqaddas qabri atrofida shakllangan. Maqbaralarning aksariyati temuriylar davrida Amir Temurning yaqinlari uchun qurilgan va har birining bezagi oʻziga xos: feruza va koʻk majolika, oʻymakor koshinlar, xattotlik. Ansamblga eski zinapoya olib boradi — rivoyatga koʻra, uning pogʻonalarini chiqishda va tushishda sanash kerak. Bu ibodat joyi, odobli kiyimda keling.",
    zh: "一条11至19世纪的陵墓街，围绕先知穆罕默德的堂弟库萨姆·伊本·阿拔斯的圣墓逐渐形成，传说中他被称为“永生之王”。大多数陵墓建于帖木儿王朝，属于帖木儿的亲属和近臣，每座都有独特的饰面：绿松石色和蓝色的釉陶、雕花瓷砖、书法铭文。一段古老的台阶通往建筑群——相传上下台阶时应数一数级数。这里是礼拜场所，请着装得体。",
    ko: "11~19세기 영묘들이 늘어선 거리로, 전설에서 ‘살아 있는 왕’이라 불리는 예언자 무함마드의 사촌 쿠삼 이븐 압바스의 묘를 중심으로 형성되었습니다. 대부분의 영묘는 티무르 시대에 아미르 티무르의 친족과 측근을 위해 지어졌고, 청록색·파란색 마졸리카, 조각 타일, 서예 등 저마다 장식이 다릅니다. 오래된 계단을 올라가는데, 오르고 내릴 때 계단 수를 세어 보라는 전설이 있습니다. 예배 장소이니 단정한 복장을 하세요.",
    de: "Eine Gräberstraße aus dem 11. bis 19. Jahrhundert, gewachsen um das verehrte Grab von Qusam ibn Abbas, einem Cousin des Propheten Mohammed, den die Legende den „Lebenden König“ nennt. Die meisten Mausoleen entstanden unter den Timuriden für Angehörige und Höflinge Timurs, jedes mit eigener Verkleidung: türkis- und blaue Majolika, geschnitzte Fliesen, Kalligrafie. Eine alte Treppe führt hinauf – der Überlieferung nach soll man ihre Stufen beim Auf- und Abstieg zählen. Es ist ein Ort des Gebets: bitte dezent kleiden.",
    fr: "Une rue de mausolées des XIe–XIXe siècles, née autour de la tombe vénérée de Qusam ibn Abbas, cousin du Prophète Mahomet, que la légende appelle le « Roi vivant ». La plupart des tombeaux furent bâtis sous les Timourides pour les proches et courtisans de Tamerlan, chacun avec son revêtement : majolique turquoise et bleue, carreaux sculptés, calligraphie. Un vieil escalier y mène – la tradition veut qu'on compte ses marches à la montée et à la descente. Lieu de culte : tenue correcte exigée.",
    ja: "11〜19世紀の霊廟が並ぶ通り。伝説で「生ける王」と呼ばれる預言者ムハンマドの従弟クサム・イブン・アッバースの聖墓を中心に形成されました。多くの霊廟はティムール朝時代にティムールの親族や側近のために建てられ、青緑や青のマジョリカ、彫りのタイル、書道装飾がそれぞれ異なります。古い階段を上って入りますが、上りと下りで段数を数えるという言い伝えがあります。礼拝の場なので控えめな服装で。",
    tr: "Peygamber Muhammed'in amcaoğlu, efsanelerde “Yaşayan Şah” diye anılan Kusem bin Abbas'ın kutsal mezarı çevresinde oluşmuş, 11.–19. yüzyıllardan kalma türbeler sokağı. Türbelerin çoğu Timurlular döneminde Timur'un yakınları için yapıldı; her birinin kaplaması farklıdır: turkuaz ve mavi majolika, oymalı çiniler, hat yazıları. Eski bir merdiven yukarı çıkar — rivayete göre basamakları çıkarken ve inerken saymak gerekir. Burası bir ibadet yeri, sade giyinin.",
    ar: "شارع من الأضرحة يعود إلى القرون من الحادي عشر إلى التاسع عشر، نشأ حول القبر المبجّل لقُثم بن العباس، ابن عم النبي محمد، الذي تسمّيه الأساطير «الملك الحي». بُنيت معظم الأضرحة في العهد التيموري لأقارب تيمور وحاشيته، ولكل منها كسوته الخاصة: خزف فيروزي وأزرق، وبلاطات منقوشة، وخط عربي. يؤدي إليه درج قديم، ويقال إن عليك عدّ درجاته صعوداً ونزولاً. إنه مكان عبادة، فارتدِ ملابس محتشمة.",
  },
  gur: {
    en: "The tomb of Amir Timur and the Timurids: here lie Timur himself, his sons Shahrukh and Miranshah, his grandsons Muhammad Sultan and Ulugh Beg, and his mentor Mir Sayyid Baraka. It was begun for Muhammad Sultan, and in 1405 Timur was buried here too. Outside rises a ribbed turquoise dome; inside is a hall with gold painting and Timur's tombstone of dark-green jade, while the actual burials are in the crypt below. The building is beautifully lit in the evening.",
    uz: "Amir Temur va temuriylar maqbarasi: bu yerda Temurning oʻzi, oʻgʻillari Shohruh va Mironshoh, nabiralari Muhammad Sulton va Ulugʻbek hamda ustozi Mir Said Baraka dafn etilgan. Maqbara Muhammad Sulton uchun qurila boshlangan, 1405 yilda bu yerga Temurning oʻzi ham dafn qilingan. Tashqarida qovurgʻali feruza gumbaz, ichkarida zarhal naqshli zal va Temurning toʻq yashil nefritdan qabrtoshi; asl qabrlar pastdagi sagʻanada. Kechqurun bino chiroyli yoritiladi.",
    zh: "帖木儿及帖木儿王朝的陵寝：这里安葬着帖木儿本人、他的儿子沙哈鲁和米兰沙、孙子穆罕默德·苏丹和兀鲁伯，以及他的导师米尔·赛义德·巴拉卡。陵墓最初为穆罕默德·苏丹而建，1405年帖木儿也葬于此。外部是带棱纹的绿松石色穹顶，内部大厅饰有金色彩绘，帖木儿的墓碑由墨绿色软玉制成，真正的墓穴在下方的墓室中。傍晚建筑亮灯，十分美丽。",
    ko: "아미르 티무르와 티무르 왕조의 영묘입니다. 티무르 자신과 아들 샤루흐·미란샤, 손자 무함마드 술탄·울루그베크, 스승 미르 사이드 바라카가 잠들어 있습니다. 원래 무함마드 술탄을 위해 짓기 시작했고, 1405년 티무르도 이곳에 묻혔습니다. 밖에는 골이 진 청록색 돔, 안에는 금빛 장식의 홀과 짙은 녹색 연옥으로 된 티무르의 묘석이 있으며 실제 매장지는 아래 지하 묘실에 있습니다. 저녁 조명이 아름답습니다.",
    de: "Die Grabstätte Timurs und der Timuriden: Hier ruhen Timur selbst, seine Söhne Schahruch und Miranschah, seine Enkel Muhammad Sultan und Ulugh Beg sowie sein Lehrer Mir Sayyid Baraka. Begonnen wurde der Bau für Muhammad Sultan; 1405 wurde auch Timur hier beigesetzt. Außen eine gerippte türkisfarbene Kuppel, innen ein Saal mit Goldmalerei und Timurs Grabstein aus dunkelgrüner Jade – die eigentlichen Gräber liegen in der Krypta darunter. Abends ist der Bau schön beleuchtet.",
    fr: "Le tombeau d'Amir Timour (Tamerlan) et des Timourides : y reposent Timour lui-même, ses fils Chahrokh et Miranchah, ses petits-fils Muhammad Sultan et Ouloug Beg, et son maître Mir Sayyid Baraka. Commencé pour Muhammad Sultan, il accueillit Timour en 1405. Dehors, un dôme turquoise côtelé ; dedans, une salle peinte à l'or et la pierre tombale de Timour en jade vert sombre — les sépultures réelles sont dans la crypte en dessous. Le monument est joliment éclairé le soir.",
    ja: "ティムールとティムール朝の霊廟。ティムール本人、息子のシャー・ルフとミーラーン・シャー、孫のムハンマド・スルタンとウルグベク、師のミール・サイイド・バラカが眠ります。もとはムハンマド・スルタンのために建て始められ、1405年にティムールもここに葬られました。外観は畝のある青緑色のドーム、内部は金彩の広間と暗緑色の軟玉でできたティムールの墓石。実際の埋葬は下の地下室にあります。夕方のライトアップが美しい。",
    tr: "Emir Timur ve Timurluların türbesi: burada Timur'un kendisi, oğulları Şahruh ile Miranşah, torunları Muhammed Sultan ile Uluğ Bey ve hocası Mir Seyyid Bereke yatar. Türbe Muhammed Sultan için yapılmaya başlandı; 1405'te Timur da buraya gömüldü. Dışarıda dilimli turkuaz bir kubbe, içeride altın süslemeli bir salon ve Timur'un koyu yeşil yeşimden mezar taşı bulunur; asıl mezarlar alttaki kriptadadır. Akşamları bina güzelce aydınlatılır.",
    ar: "ضريح الأمير تيمور والتيموريين: يرقد هنا تيمور نفسه، وابناه شاه رخ وميران شاه، وحفيداه محمد سلطان وأولوغ بيك، ومعلّمه مير سيد بركة. بدأ بناؤه لمحمد سلطان، وفي عام 1405 دُفن فيه تيمور أيضاً. في الخارج قبة فيروزية مضلّعة، وفي الداخل قاعة بزخارف ذهبية وشاهد قبر تيمور من اليشم الأخضر الداكن، أما المدافن الحقيقية ففي السرداب أسفلها. يُضاء المبنى مساءً بشكل جميل.",
  },
  bibi: {
    en: "The congregational mosque Amir Timur built in 1399–1404 after his Indian campaign — one of the largest in the Islamic world of its time. It is named after Timur's senior wife, Saray Mulk Khanum, and several beautiful but disputed legends are told about it. Damaged by earthquakes, it has been restored; in the courtyard stands a huge marble Quran stand. The Siab Bazaar and Shah-i-Zinda are next door, easy to see in one walk.",
    uz: "Amir Temur Hindiston yurishidan soʻng 1399–1404 yillarda qurdirgan jome masjidi — oʻz davrida islom olamidagi eng yiriklaridan biri. U Temurning katta xotini Saroy Mulk xonim nomi bilan atalgan, bu haqda bir necha goʻzal, ammo bahsli rivoyatlar bor. Masjid zilzilalardan zarar koʻrgan va qayta tiklangan; hovlida ulkan marmar lavh — Qurʼon qoʻyiladigan kursi turadi. Yonida Siyob bozori va Shohi Zinda — ularni bir sayrda koʻrish qulay.",
    zh: "帖木儿在远征印度后于1399–1404年修建的聚礼清真寺，是当时伊斯兰世界最大的清真寺之一。它以帖木儿的正妻萨莱·穆尔克·哈努姆命名，围绕它流传着几则美丽却有争议的传说。清真寺曾因地震受损，后经修复；院中立着一座巨大的大理石《古兰经》经台。旁边就是夏布集市和沙赫静达，一次散步即可游览。",
    ko: "아미르 티무르가 인도 원정 후 1399~1404년에 지은 금요 모스크로, 당대 이슬람 세계에서 가장 큰 모스크 중 하나였습니다. 티무르의 정실 사라이 물크 하눔의 이름을 땄으며, 아름답지만 논란이 있는 전설이 여럿 전해집니다. 지진으로 손상되었다가 복원되었고, 안뜰에는 거대한 대리석 코란 받침대가 있습니다. 바로 옆 시압 바자르와 샤히 진다를 한 번에 둘러보기 좋습니다.",
    de: "Die Freitagsmoschee, die Timur 1399–1404 nach seinem Indienfeldzug errichten ließ – eine der größten der damaligen islamischen Welt. Benannt ist sie nach Timurs Hauptfrau Saray Mulk Chanum; um sie ranken sich mehrere schöne, aber umstrittene Legenden. Nach Erdbebenschäden wurde sie restauriert; im Hof steht ein riesiges Marmorpult für den Koran. Der Siab-Basar und Schah-i-Sinda liegen gleich nebenan – gut in einem Rundgang zu verbinden.",
    fr: "La mosquée-cathédrale que Tamerlan fit bâtir en 1399–1404 après sa campagne d'Inde — l'une des plus grandes du monde islamique de son temps. Elle porte le nom de son épouse principale, Saray Mulk Khanoum, au cœur de plusieurs légendes aussi belles que discutées. Endommagée par les séismes, elle a été restaurée ; dans la cour trône un immense lutrin de marbre pour le Coran. Le bazar Siab et Chah-i-Zinda sont à côté : une seule promenade suffit.",
    ja: "ティムールがインド遠征後の1399〜1404年に建てた金曜モスクで、当時のイスラム世界で最大級のもの。ティムールの正妃サライ・ムルク・ハヌムの名を冠し、美しくも真偽の定かでない伝説がいくつも残ります。地震で損傷した後に修復され、中庭には巨大な大理石のコーラン台が置かれています。隣のシアブ・バザールとシャーヒ・ズィンダと合わせて一度に巡れます。",
    tr: "Emir Timur'un Hindistan seferinden sonra 1399–1404'te yaptırdığı cuma camii — döneminin İslam dünyasındaki en büyüklerinden biri. Adını Timur'un büyük eşi Saray Mülk Hanım'dan alır; hakkında güzel ama tartışmalı birkaç efsane anlatılır. Depremlerde hasar gördükten sonra restore edildi; avluda devasa bir mermer rahle durur. Hemen yanındaki Siyab Pazarı ve Şah-ı Zinde'yi tek yürüyüşte gezebilirsiniz.",
    ar: "المسجد الجامع الذي بناه الأمير تيمور بين 1399 و1404 بعد حملته على الهند، وكان من أكبر مساجد العالم الإسلامي في عصره. سُمّي باسم زوجة تيمور الكبرى سراي ملك خانم، وتُروى عنه عدة أساطير جميلة لكنها موضع خلاف. تضرّر من الزلازل ثم رُمّم، وفي فنائه حامل رخامي ضخم للمصحف. بجواره سوق سياب وشاه زنده، فيسهل زيارتها في نزهة واحدة.",
  },
  ulug: {
    en: "The remains of the observatory built in the 1420s by Timur's grandson Mirzo Ulugh Beg. Its main instrument was a giant sextant: the underground part cut into the rock survived and was excavated in 1908 by the archaeologist Vasily Vyatkin. Here the “Zij” was compiled — a catalogue of 1,018 stars, the most accurate of its time. Next to it is the Ulugh Beg Museum with a model of the observatory, copies of manuscripts and a monument to the scholar.",
    uz: "Temurning nabirasi Mirzo Ulugʻbek 1420-yillarda qurdirgan rasadxona qoldiqlari. Uning asosiy asbobi ulkan sekstant boʻlgan: qoyaga oʻyib ishlangan yer osti qismi saqlanib qolgan va 1908 yilda arxeolog Vasiliy Vyatkin tomonidan topilgan. Bu yerda «Zij» — oʻz davrining eng aniq 1018 yulduzli katalogi tuzilgan. Yonida Ulugʻbek muzeyi: rasadxona maketi, qoʻlyozmalar nusxalari va olimga haykal.",
    zh: "帖木儿之孙兀鲁伯于15世纪20年代修建的天文台遗址。其主要仪器是一座巨大的六分仪：凿入岩石的地下部分得以保存，1908年由考古学家瓦西里·维亚特金发掘出来。这里编制了《兀鲁伯天文表》——收录1018颗星的星表，是当时最精确的。旁边是兀鲁伯博物馆，有天文台模型、手稿复制品和学者纪念像。",
    ko: "티무르의 손자 미르조 울루그베크가 1420년대에 세운 천문대 유적입니다. 주 관측 기구는 거대한 육분의였는데, 바위를 깎아 만든 지하 부분이 남아 1908년 고고학자 바실리 뱟킨이 발굴했습니다. 이곳에서 당대 가장 정확한 1,018개 별의 목록 ‘지즈’가 만들어졌습니다. 옆에는 천문대 모형, 필사본 사본, 학자 기념상이 있는 울루그베크 박물관이 있습니다.",
    de: "Die Reste der Sternwarte, die Timurs Enkel Mirzo Ulugh Beg in den 1420er-Jahren erbauen ließ. Ihr Hauptinstrument war ein riesiger Sextant: Der in den Fels geschnittene unterirdische Teil blieb erhalten und wurde 1908 vom Archäologen Wassili Wjatkin freigelegt. Hier entstand der „Zij“ – ein Katalog von 1018 Sternen, der genaueste seiner Zeit. Daneben liegt das Ulugh-Beg-Museum mit Modell der Sternwarte, Handschriftenkopien und einem Denkmal des Gelehrten.",
    fr: "Les vestiges de l'observatoire construit dans les années 1420 par Mirzo Ouloug Beg, petit-fils de Tamerlan. Son instrument principal était un sextant géant : la partie souterraine taillée dans la roche a survécu et fut dégagée en 1908 par l'archéologue Vassili Viatkine. On y établit le « Zij », un catalogue de 1 018 étoiles, le plus précis de son temps. À côté, le musée Ouloug Beg présente une maquette de l'observatoire, des copies de manuscrits et un monument au savant.",
    ja: "ティムールの孫ミルザ・ウルグベクが1420年代に建てた天文台の遺構。主要な観測器は巨大な六分儀で、岩を掘り込んだ地下部分が残り、1908年に考古学者ワシーリー・ヴャトキンが発掘しました。ここで当時最も正確な1018個の星表「ズィージュ」が編まれました。隣のウルグベク博物館には天文台の模型、写本の複製、学者の像があります。",
    tr: "Timur'un torunu Mirza Uluğ Bey'in 1420'lerde yaptırdığı rasathanenin kalıntıları. Ana aleti dev bir sekstantmış: kayaya oyulmuş yeraltı kısmı günümüze ulaştı ve 1908'de arkeolog Vasiliy Vyatkin tarafından ortaya çıkarıldı. Burada dönemin en doğru kataloğu olan 1018 yıldızlık “Zic” hazırlandı. Yanında rasathane maketi, el yazması kopyaları ve bilgin anıtıyla Uluğ Bey Müzesi bulunur.",
    ar: "بقايا المرصد الذي بناه ميرزا أولوغ بيك حفيد تيمور في عشرينيات القرن الخامس عشر. كانت أداته الرئيسية سدسية عملاقة نجا جزؤها المحفور في الصخر تحت الأرض، واكتشفه عالم الآثار فاسيلي فياتكين عام 1908. هنا وُضع «الزيج»، فهرس لـ1018 نجماً كان الأدق في زمانه. وإلى جانبه متحف أولوغ بيك بمجسّم للمرصد ونسخ من المخطوطات ونصب للعالِم.",
  },
  afros: {
    en: "The Museum of the History of Samarkand next to the ancient Afrasiyab site, opened in 1970. Its treasure is a set of 7th-century Sogdian murals from the palace of King Varkhuman: envoys bearing gifts, processions and court life — one of the best-known finds in Central Asia. There are also ossuaries, ceramics, coins and weapons from ancient Marakanda; after the museum you can climb the hills of the site itself.",
    uz: "Qadimiy Afrosiyob shahar xarobasi yonidagi Samarqand tarixi muzeyi, 1970 yilda ochilgan. Asosiy boyligi — hukmdor Varxuman saroyidagi VII asr soʻgʻd devoriy suratlari: sovgʻa olib kelgan elchilar, kortejlar, saroy hayoti. Bu Markaziy Osiyodagi eng mashhur topilmalardan biri. Bu yerda qadimiy Marakanda ossuariylari, sopol buyumlar, tangalar va qurollar ham bor; muzeydan soʻng xarobaning tepaliklariga chiqish mumkin.",
    zh: "撒马尔罕历史博物馆位于阿夫拉西阿卜古城遗址旁，1970年开馆。镇馆之宝是来自瓦尔胡曼王宫的7世纪粟特壁画：携礼而来的使节、仪仗队和宫廷生活，是中亚最著名的发现之一。这里还有古马拉坎达的骨瓮、陶器、钱币和兵器；参观后可以登上遗址的山丘。",
    ko: "고대 아프라시압 유적 옆에 있는 사마르칸트 역사 박물관으로 1970년에 개관했습니다. 최고의 보물은 바르후만 왕 궁전의 7세기 소그드 벽화로, 선물을 든 사절과 행렬, 궁정 생활을 담은 중앙아시아의 가장 유명한 발견 중 하나입니다. 고대 마라칸다의 납골함, 도자기, 동전, 무기도 있으며 관람 후 유적 언덕에 올라가 볼 수 있습니다.",
    de: "Das Museum der Geschichte Samarkands an der antiken Stätte Afrasiab, eröffnet 1970. Sein Schatz sind sogdische Wandmalereien des 7. Jahrhunderts aus dem Palast des Königs Warchuman: Gesandte mit Geschenken, Prozessionen, Hofleben – einer der bekanntesten Funde Zentralasiens. Außerdem Ossuarien, Keramik, Münzen und Waffen des alten Marakanda; danach lohnt ein Spaziergang über die Hügel der Stätte.",
    fr: "Le musée d'histoire de Samarcande, ouvert en 1970 au bord du site antique d'Afrasiab. Son trésor : des peintures murales sogdiennes du VIIe siècle venues du palais du roi Varkhuman — ambassadeurs chargés de présents, processions, vie de cour —, l'une des découvertes les plus célèbres d'Asie centrale. On y voit aussi ossuaires, céramiques, monnaies et armes de l'antique Maracanda ; après la visite, montez sur les collines du site.",
    ja: "古代遺跡アフラシアブのそばにあるサマルカンド歴史博物館（1970年開館）。至宝はヴァルフマン王の宮殿を飾った7世紀のソグド壁画で、贈り物を携えた使節や行列、宮廷生活が描かれた中央アジア屈指の発見です。古代マラカンダの納骨器、陶器、硬貨、武器も展示。見学後は遺跡の丘を歩けます。",
    tr: "Antik Afrasiyab kalıntılarının yanındaki Semerkant Tarihi Müzesi, 1970'te açıldı. En değerli eseri, Kral Varhuman'ın sarayından 7. yüzyıl Soğd duvar resimleri: armağan getiren elçiler, alaylar ve saray yaşamı — Orta Asya'nın en ünlü buluntularından biri. Antik Marakanda'dan osuarlar, seramikler, sikkeler ve silahlar da sergilenir; müzeden sonra kalıntıların tepelerine çıkabilirsiniz.",
    ar: "متحف تاريخ سمرقند بجوار موقع أفراسياب القديم، افتُتح عام 1970. أثمن ما فيه جداريات صغدية من القرن السابع من قصر الملك فرخومان: سفراء يحملون الهدايا ومواكب وحياة البلاط، وهي من أشهر الاكتشافات في آسيا الوسطى. يضم أيضاً نواويس وخزفاً وعملات وأسلحة من مرقندة القديمة، وبعد الزيارة يمكنك صعود تلال الموقع.",
  },
  savsav: {
    en: "Samarkand's main bazaar by the walls of the Bibi-Khanym Mosque. It sells Samarkand flatbread, nuts, dried fruit, spices, halva and navat — crystal sugar for tea — and mountains of fruit in summer and autumn. Some rows are covered, so you can come even in the heat. Bargaining is normal; ask before photographing the sellers.",
    uz: "Bibixonim masjidi devorlari yonidagi Samarqandning bosh bozori. Bu yerda Samarqand noni, yongʻoq, quruq meva, ziravorlar, holva va choy uchun navvot, yozu kuzda esa togʻ-togʻ mevalar sotiladi. Rastalarning bir qismi yopiq, shuning uchun jaziramada ham kelish mumkin. Savdolashish odatiy hol, sotuvchilarni suratga olishdan oldin ruxsat soʻrang.",
    zh: "撒马尔罕的主要集市，就在比比哈努姆清真寺墙边。这里卖撒马尔罕馕、坚果、果干、香料、哈尔瓦糖和配茶的结晶糖“纳瓦特”，夏秋两季水果堆积如山。部分摊位有顶棚，炎热天也能来逛。讨价还价很正常，拍摄摊主前请先征得同意。",
    ko: "비비하눔 모스크 담장 옆에 있는 사마르칸트의 대표 시장입니다. 사마르칸트 빵, 견과류, 말린 과일, 향신료, 할바, 차에 넣는 결정 설탕 나바트를 팔고, 여름과 가을엔 과일이 산더미처럼 쌓입니다. 일부 구역은 지붕이 있어 더운 날에도 좋습니다. 흥정은 자연스러운 일이며, 상인을 찍을 땐 먼저 허락을 구하세요.",
    de: "Samarkands Hauptbasar an den Mauern der Bibi-Chanum-Moschee. Hier gibt es Samarkander Fladenbrot, Nüsse, Trockenfrüchte, Gewürze, Halwa und Nawat – Kristallzucker zum Tee – sowie im Sommer und Herbst Berge von Obst. Ein Teil der Reihen ist überdacht, man kann also auch bei Hitze kommen. Handeln ist üblich; Verkäufer bitte vor dem Fotografieren fragen.",
    fr: "Le grand bazar de Samarcande, au pied des murs de la mosquée Bibi-Khanoum. On y trouve le pain de Samarcande, des noix, des fruits secs, des épices, du halva et du navat — sucre cristallisé pour le thé —, et des montagnes de fruits en été et en automne. Une partie des allées est couverte : on peut venir même par forte chaleur. On marchande volontiers ; demandez avant de photographier les vendeurs.",
    ja: "ビビ・ハヌム・モスクの壁際にあるサマルカンド最大のバザール。サマルカンドのナン、ナッツ、ドライフルーツ、スパイス、ハルヴァ、お茶に入れる結晶砂糖ナヴァトが並び、夏から秋は果物が山積みに。一部は屋根付きなので暑い日も歩けます。値切るのは普通のこと。売り手を撮るときは一声かけて。",
    tr: "Bibi Hanım Camii'nin duvarları dibindeki Semerkant'ın ana pazarı. Semerkant ekmeği, ceviz, kuru meyve, baharat, helva ve çay için kristal şeker navat satılır; yaz ve sonbaharda meyveler dağ gibi yığılır. Sıraların bir kısmı kapalı, sıcakta da gelebilirsiniz. Pazarlık olağandır; satıcıları fotoğraflamadan önce izin isteyin.",
    ar: "السوق الرئيسي في سمرقند عند أسوار مسجد بيبي خانم. يُباع فيه خبز سمرقند والمكسرات والفواكه المجففة والتوابل والحلاوة و«النبات» — سكر متبلور للشاي — وجبال من الفاكهة صيفاً وخريفاً. بعض الممرات مسقوفة، فيمكن المجيء حتى في الحر. المساومة أمر معتاد، واستأذن قبل تصوير الباعة.",
  },
  meros: {
    en: "A workshop in Konigil village on the edge of Samarkand, where the Mukhtarov brothers revived handmade Samarkand paper from mulberry bark. You can watch the whole process — from soaking the bark to polishing the sheet with a stone — see the water wheel and wooden machinery, and buy notebooks and postcards. Around it lies a shady village with teahouses by the water.",
    uz: "Samarqand chetidagi Konigil qishlogʻidagi ustaxona: bu yerda aka-uka Muxtorovlar tut poʻstlogʻidan qoʻlda mashhur Samarqand qogʻozini tayyorlashni qayta tiklagan. Poʻstloqni ivitishdan tortib varaqni tosh bilan silliqlashgacha butun jarayonni, suv charxpalagi va yogʻoch mexanizmlarni koʻrish, keyin bloknot va otkritkalar xarid qilish mumkin. Atrofda suv boʻyida choyxonalari bor soyali qishloq.",
    zh: "撒马尔罕郊外科尼吉尔村的作坊，穆赫塔罗夫兄弟在这里复兴了用桑树皮手工制作著名撒马尔罕纸的工艺。你可以看到从浸泡树皮到用石头打磨纸张的全过程、水车和木制机械，还能买到笔记本和明信片。周围是绿荫浓密、水边有茶馆的村庄。",
    ko: "사마르칸트 외곽 코니길 마을의 공방으로, 무흐타로프 형제가 뽕나무 껍질로 만드는 사마르칸트 수제 종이를 되살렸습니다. 껍질을 불리는 것부터 돌로 종이를 윤내는 것까지 전 과정과 물레방아, 나무 기계를 볼 수 있고 노트와 엽서도 살 수 있습니다. 주변은 물가에 찻집이 있는 그늘진 마을입니다.",
    de: "Eine Werkstatt im Dorf Konigil am Stadtrand von Samarkand, in der die Brüder Muchtarow das handgeschöpfte Samarkand-Papier aus Maulbeerbaumrinde wiederbelebt haben. Man sieht den ganzen Weg des Blattes – vom Einweichen der Rinde bis zum Polieren mit einem Stein –, das Wasserrad und die Holzmechanik, und kann Notizbücher und Postkarten kaufen. Ringsum ein schattiges Dorf mit Teehäusern am Wasser.",
    fr: "Un atelier du village de Konigil, aux portes de Samarcande, où les frères Moukhtarov ont fait renaître le célèbre papier de Samarcande fait main à partir d'écorce de mûrier. On suit tout le parcours de la feuille — du trempage de l'écorce au polissage à la pierre —, on voit la roue à eau et les mécanismes en bois, puis on achète carnets et cartes. Autour, un village ombragé avec des maisons de thé au bord de l'eau.",
    ja: "サマルカンド郊外コニギル村の工房。ムフタロフ兄弟が桑の樹皮から作る手漉きのサマルカンド紙を復活させました。樹皮を浸すところから石で紙を磨くまでの全工程、水車や木製の機械を見学でき、ノートやポストカードも買えます。周囲は水辺にチャイハナが並ぶ緑陰の村です。",
    tr: "Semerkant'ın kenarındaki Konigil köyünde bir atölye: Muhtarov kardeşler burada dut kabuğundan elde yapılan ünlü Semerkant kâğıdını yeniden canlandırdı. Kabuğun ıslatılmasından yaprağın taşla parlatılmasına kadar tüm süreci, su çarkını ve ahşap düzenekleri görebilir, defter ve kartpostal alabilirsiniz. Çevrede su kenarında çayhaneleri olan gölgeli bir köy var.",
    ar: "ورشة في قرية كونيغيل على أطراف سمرقند، أحيا فيها الأخوان مختاروف صناعة ورق سمرقند الشهير يدوياً من لحاء التوت. يمكنك مشاهدة المراحل كلها، من نقع اللحاء إلى صقل الورقة بالحجر، ورؤية الناعورة والآلات الخشبية، ثم شراء دفاتر وبطاقات. وحولها قرية ظليلة فيها مقاهٍ للشاي على الماء.",
  },
  smafr: {
    en: "Hills on the northern edge of the city — the site of ancient Marakanda, capital of Sogdiana. A city stood here from the 8th–7th centuries BC until the Mongols destroyed it in the 13th century; its people then moved south to where Samarkand is today. The site covers more than 200 hectares and has been excavated since the 19th century. It is an open archaeological area next to the Afrasiyab Museum and the Hazrat Khizr Mosque.",
    uz: "Shaharning shimoliy chetidagi tepaliklar — Soʻgʻdiyona poytaxti qadimiy Marakanda oʻrni. Bu yerda miloddan avvalgi VIII–VII asrlardan XIII asrda moʻgʻullar vayron qilguncha shahar boʻlgan; keyin aholi janubga, hozirgi Samarqand oʻrniga koʻchgan. Xaroba maydoni 200 gektardan ortiq, qazishmalar XIX asrdan beri olib boriladi. Bu Afrosiyob muzeyi va Hazrati Xizr masjidi yonidagi ochiq arxeologik hudud.",
    zh: "城市北缘的山丘，是粟特首都古马拉坎达的所在地。从公元前8–7世纪起这里便有城市，直到13世纪被蒙古人摧毁，居民随后南迁到今天撒马尔罕所在之处。遗址面积超过200公顷，自19世纪起持续发掘。这是一片开放的考古区，紧邻阿夫拉西阿卜博物馆和哈兹拉特·希兹尔清真寺。",
    ko: "도시 북쪽 가장자리의 언덕들로, 소그디아나의 수도였던 고대 마라칸다 자리입니다. 기원전 8~7세기부터 13세기 몽골에 파괴될 때까지 도시가 있었고, 이후 주민들은 오늘날 사마르칸트가 있는 남쪽으로 옮겨 갔습니다. 유적 면적은 200헥타르가 넘고 19세기부터 발굴이 이어지고 있습니다. 아프라시압 박물관과 하즈라트 히즈르 모스크 옆의 개방된 고고학 지역입니다.",
    de: "Hügel am Nordrand der Stadt – der Ort des antiken Marakanda, Hauptstadt Sogdiens. Hier stand vom 8.–7. Jahrhundert v. Chr. eine Stadt, bis die Mongolen sie im 13. Jahrhundert zerstörten; die Bewohner zogen dann nach Süden, wo heute Samarkand liegt. Die Stätte umfasst über 200 Hektar und wird seit dem 19. Jahrhundert ausgegraben. Ein offenes archäologisches Gelände neben dem Afrasiab-Museum und der Hazrat-Chisr-Moschee.",
    fr: "Des collines au nord de la ville : le site de l'antique Maracanda, capitale de la Sogdiane. Une ville y exista du VIIIe–VIIe siècle av. J.-C. jusqu'à sa destruction par les Mongols au XIIIe siècle ; ses habitants s'installèrent alors plus au sud, là où se trouve Samarcande aujourd'hui. Le site couvre plus de 200 hectares et est fouillé depuis le XIXe siècle. C'est un espace archéologique ouvert, à côté du musée d'Afrasiab et de la mosquée Hazrat Khizr.",
    ja: "市の北端に広がる丘陵で、ソグディアナの都・古代マラカンダの跡。紀元前8〜7世紀から13世紀にモンゴルに破壊されるまで都市があり、その後住民は南の現在のサマルカンドへ移りました。遺跡は200ヘクタール以上、19世紀から発掘が続きます。アフラシアブ博物館とハズラト・ヒズル・モスクの隣にある開放された考古学エリアです。",
    tr: "Şehrin kuzey ucundaki tepeler — Soğdiana'nın başkenti antik Marakanda'nın yeri. Burada MÖ 8.–7. yüzyıldan 13. yüzyılda Moğollar yıkana kadar bir şehir vardı; halk daha sonra bugünkü Semerkant'ın bulunduğu güneye taşındı. Alan 200 hektardan büyüktür ve 19. yüzyıldan beri kazılıyor. Afrasiyab Müzesi ile Hazreti Hızır Camii'nin yanında açık bir arkeolojik alan.",
    ar: "تلال على الطرف الشمالي للمدينة، هي موقع مرقندة القديمة عاصمة الصغد. قامت هنا مدينة منذ القرنين الثامن والسابع قبل الميلاد حتى دمّرها المغول في القرن الثالث عشر، فانتقل سكانها جنوباً إلى حيث تقع سمرقند اليوم. تزيد مساحة الموقع على 200 هكتار، والتنقيب فيه مستمر منذ القرن التاسع عشر. إنه منطقة أثرية مفتوحة بجوار متحف أفراسياب ومسجد حضرة الخضر.",
  },
  smahrar: {
    en: "A quiet ensemble in the south of Samarkand around the grave of Khoja Ahrar (died 1490), an influential sheikh of the Naqshbandi Sufi order. His tombstone is a large slab with fine carved calligraphy. In the 1630s the Nadir Divan-Begi Madrasa was built beside it — called the “mirror of Sher-Dor” for its similar décor — and later a winter mosque and a minaret. After earthquakes the ensemble was restored from old photographs; huge plane trees grow in the courtyard.",
    uz: "Samarqand janubidagi Naqshbandiya tariqatining nufuzli shayxi Xoʻja Ahror (1490 yilda vafot etgan) qabri atrofidagi sokin ansambl. Uning qabrtoshi nozik oʻymakor xattotlik bilan bezatilgan katta tosh lavhadir. 1630-yillarda yonida bezaklari oʻxshashligi uchun «Sherdorning koʻzgusi» deb ataluvchi Nodir devonbegi madrasasi, keyinroq qishki masjid va minora qurilgan. Zilzilalardan soʻng ansambl eski fotosuratlar asosida tiklangan; hovlida ulkan chinorlar oʻsadi.",
    zh: "撒马尔罕南部一处宁静的建筑群，围绕纳克什班迪苏非教团颇具影响力的谢赫霍贾·阿赫拉尔（1490年去世）之墓而建。他的墓碑是一块刻有精美书法的大石板。17世纪30年代旁边修建了纳迪尔·迪万·别吉经学院，因装饰相似被称为“希尔多尔的镜子”，之后又建了冬季清真寺和宣礼塔。地震后建筑群依据老照片修复；院中生长着巨大的悬铃木。",
    ko: "사마르칸트 남쪽의 조용한 앙상블로, 낙쉬반디 수피 교단의 영향력 있는 셰이크 호자 아흐라르(1490년 사망)의 묘를 중심으로 합니다. 그의 묘석은 섬세한 서예가 새겨진 큰 석판입니다. 1630년대에 장식이 비슷해 ‘셰르도르의 거울’로 불리는 나디르 디반베기 마드라사가, 이후 겨울 모스크와 미나렛이 세워졌습니다. 지진 후 옛 사진을 바탕으로 복원되었고 안뜰에는 거대한 플라타너스가 자랍니다.",
    de: "Ein stilles Ensemble im Süden Samarkands um das Grab von Chodscha Ahrar († 1490), einem einflussreichen Scheich des Naqschbandi-Sufiordens. Sein Grabstein ist eine große Platte mit feiner geschnitzter Kalligrafie. In den 1630er-Jahren entstand daneben die Medrese Nadir Diwan-Begi, wegen ihres ähnlichen Dekors „Spiegel von Scher-Dor“ genannt, später eine Wintermoschee und ein Minarett. Nach Erdbeben wurde das Ensemble nach alten Fotos restauriert; im Hof stehen riesige Platanen.",
    fr: "Un ensemble paisible au sud de Samarcande, autour de la tombe de Khodja Ahrar (mort en 1490), cheikh influent de la confrérie soufie Naqshbandiya. Sa pierre tombale est une grande dalle à la calligraphie finement sculptée. Dans les années 1630 fut bâtie à côté la médersa Nadir Divan-Beghi, surnommée « miroir du Cher-Dor » pour son décor proche, puis une mosquée d'hiver et un minaret. Après les séismes, l'ensemble a été restauré d'après de vieilles photos ; d'immenses platanes ombragent la cour.",
    ja: "サマルカンド南部の静かな建築群で、ナクシュバンディー教団の有力なシャイフ、ホージャ・アフラール（1490年没）の墓を中心としています。墓石は繊細な書の彫刻が施された大きな石板。1630年代には装飾が似ていることから「シェルドルの鏡」と呼ばれるナディル・ディヴァンベギ・メドレセが、のちに冬のモスクとミナレットが建てられました。地震後、古写真をもとに修復され、中庭には巨大なプラタナスが茂ります。",
    tr: "Semerkant'ın güneyinde, Nakşibendi tarikatının nüfuzlu şeyhi Hoca Ahrar'ın (ö. 1490) mezarı çevresinde sakin bir külliye. Mezar taşı, ince oymalı hatlarla süslü büyük bir levhadır. 1630'larda yanına, benzer süslemesi nedeniyle “Şirdar'ın aynası” denen Nadir Divanbeyi Medresesi, sonra bir kış camii ve minare yapıldı. Depremlerden sonra külliye eski fotoğraflara göre restore edildi; avluda dev çınarlar yükselir.",
    ar: "مجمع هادئ جنوبي سمرقند حول قبر خوجة أحرار (توفي 1490)، الشيخ النافذ في الطريقة النقشبندية الصوفية. شاهد قبره لوح كبير عليه خط عربي منقوش بدقة. في ثلاثينيات القرن السابع عشر بُنيت بجانبه مدرسة نادر ديوان بيكي التي تُلقّب بـ«مرآة شير دور» لتشابه زخارفها، ثم مسجد شتوي ومئذنة. رُمّم المجمع بعد الزلازل استناداً إلى صور قديمة، وفي فنائه أشجار دلب ضخمة.",
  },
  smaksr: {
    en: "A small 15th-century tomb a few steps from Gur-e Amir, believed to have been built for descendants of the ruler Abu Said, Timur's great-grandson. Plain outside, it hides gold painting on its walls and dome — rare for Samarkand. During the 2007 restoration part of a wall was deliberately left with its original finish. Who is buried in the crypt is not known for certain.",
    uz: "Goʻri Amirdan bir necha qadam narida joylashgan XV asrga oid kichik maqbara; u Temurning chevarasi Abu Saidning avlodlari uchun qurilgan deb hisoblanadi. Tashqaridan koʻzga tashlanmaydi, ammo ichida devor va gumbazdagi Samarqand uchun noyob zarhal naqshlar bor. 2007 yilgi taʼmirda devorning bir qismi ataylab asl bezagi bilan qoldirilgan. Sagʻanada kim dafn etilgani aniq maʼlum emas.",
    zh: "距古尔-埃米尔几步之遥的15世纪小陵墓，据信为帖木儿曾孙、统治者阿布·赛义德的后裔所建。外观朴素，内部墙壁和穹顶却有撒马尔罕罕见的金色彩绘。2007年修复时特意保留了一段原有装饰的墙面。墓室中安葬的是谁至今不得而知。",
    ko: "구르에미르에서 몇 걸음 떨어진 15세기의 작은 영묘로, 티무르의 증손자인 통치자 아부 사이드의 후손을 위해 지은 것으로 여겨집니다. 겉은 수수하지만 안쪽 벽과 돔에는 사마르칸트에서 보기 드문 금빛 장식이 있습니다. 2007년 복원 때 벽 일부는 일부러 원래 마감을 남겼습니다. 지하 묘실에 누가 묻혔는지는 확실히 알려지지 않았습니다.",
    de: "Ein kleines Grabmal aus dem 15. Jahrhundert wenige Schritte von Gur-Emir, vermutlich für Nachkommen des Herrschers Abu Said, eines Urenkels Timurs, erbaut. Außen unscheinbar, birgt es an Wänden und Kuppel eine für Samarkand seltene Goldmalerei. Bei der Restaurierung 2007 wurde ein Wandstück bewusst mit der Originalfassung belassen. Wer in der Krypta liegt, ist nicht sicher bekannt.",
    fr: "Un petit tombeau du XVe siècle à quelques pas du Gour-Emir, sans doute élevé pour des descendants du souverain Abou Saïd, arrière-petit-fils de Tamerlan. Sobre au-dehors, il cache sur ses murs et sa coupole une peinture à l'or rare à Samarcande. Lors de la restauration de 2007, un pan de mur a été volontairement laissé avec son décor d'origine. On ignore qui repose dans la crypte.",
    ja: "グーリ・アミールから数歩の15世紀の小さな霊廟で、ティムールの曾孫である君主アブー・サイードの子孫のために建てられたと考えられています。外観は質素ですが、内部の壁とドームにはサマルカンドでは珍しい金彩が施されています。2007年の修復では壁の一部があえて当初の仕上げのまま残されました。地下室に誰が眠るのかは確かではありません。",
    tr: "Gur-i Emir'e birkaç adım uzaklıkta 15. yüzyıldan küçük bir türbe; Timur'un torununun oğlu hükümdar Ebu Said'in torunları için yapıldığı düşünülür. Dışı sade, ama içinde duvarlarda ve kubbede Semerkant'ta ender görülen altın süsleme var. 2007 restorasyonunda bir duvar parçası bilerek orijinal hâliyle bırakıldı. Kriptada kimin yattığı kesin olarak bilinmiyor.",
    ar: "ضريح صغير من القرن الخامس عشر على بعد خطوات من غور أمير، يُعتقد أنه بُني لأحفاد الحاكم أبي سعيد، حفيد حفيد تيمور. بسيط من الخارج، لكنه يخفي في جدرانه وقبته زخارف ذهبية نادرة في سمرقند. في ترميم عام 2007 تُرك جزء من جدار عمداً بزخرفته الأصلية. ولا يُعرف على وجه اليقين من دُفن في السرداب.",
  },
  smishr: {
    en: "Majestic 15th-century ruins in the south-east of the city. The mausoleum was raised by Habiba Sultan Begim, wife of the ruler Abu Said, over their daughter's grave; later Timurid women were buried here — excavations in 1940 found their tombs. The name is translated as “house of joy”, which inspired a legend about Timur's feasts, though the building came after him. The dome fell in the 1903 earthquake, but the scale of the building is still clear.",
    uz: "Shaharning janubi-sharqidagi XV asrga oid ulugʻvor xarobalar. Maqbarani hukmdor Abu Saidning rafiqasi Habiba Sulton begim qizlarining qabri ustiga qurdirgan; keyinroq bu yerda temuriy ayollar dafn etilgan — 1940 yilgi qazishmalarda ularning qabrlari topilgan. Nomi «shodlik uyi» deb tarjima qilinadi va u Temurning ziyofatlari haqidagi afsonaga sabab boʻlgan, garchi bino undan keyin qurilgan boʻlsa ham. Gumbaz 1903 yilgi zilzilada qulagan, ammo binoning koʻlami hozir ham yaqqol koʻrinadi.",
    zh: "城市东南部壮观的15世纪遗迹。这座陵墓由统治者阿布·赛义德的妻子哈比巴·苏丹·别吉姆在女儿墓上修建；后来帖木儿王朝的女性也葬于此——1940年的发掘找到了她们的墓葬。名称意为“欢乐之屋”，由此衍生出帖木儿在此宴饮的传说，尽管建筑建于他身后。穹顶在1903年地震中坍塌，但建筑的宏大规模依然清晰可见。",
    ko: "도시 남동쪽의 웅장한 15세기 유적입니다. 통치자 아부 사이드의 아내 하비바 술탄 베김이 딸의 묘 위에 세웠고, 이후 티무르 왕조 여성들이 이곳에 묻혔습니다(1940년 발굴로 확인). 이름은 ‘기쁨의 집’으로 번역되어 티무르의 연회 전설이 생겼지만 건물은 그 이후에 지어졌습니다. 돔은 1903년 지진으로 무너졌지만 건물의 규모는 지금도 뚜렷합니다.",
    de: "Majestätische Ruinen aus dem 15. Jahrhundert im Südosten der Stadt. Habiba Sultan Begim, Frau des Herrschers Abu Said, ließ das Mausoleum über dem Grab ihrer Tochter errichten; später wurden hier Frauen der Timuriden bestattet – Grabungen 1940 fanden ihre Gräber. Der Name bedeutet „Haus der Freude“, woraus eine Legende über Timurs Gelage entstand, obwohl der Bau erst nach ihm entstand. Die Kuppel stürzte beim Erdbeben 1903 ein, doch die Größe des Baus ist noch gut zu erkennen.",
    fr: "Des ruines majestueuses du XVe siècle au sud-est de la ville. Le mausolée fut élevé par Habiba Sultan Beguim, épouse du souverain Abou Saïd, sur la tombe de leur fille ; des femmes timourides y furent ensuite inhumées — les fouilles de 1940 ont retrouvé leurs tombes. Le nom signifie « maison de la joie », d'où une légende sur les festins de Tamerlan, bien que l'édifice lui soit postérieur. La coupole s'est effondrée lors du séisme de 1903, mais l'ampleur du monument reste saisissante.",
    ja: "市の南東にある15世紀の壮大な廃墟。君主アブー・サイードの妃ハビーバ・スルタン・ベギムが娘の墓の上に建て、のちにティムール朝の女性たちが葬られました（1940年の発掘で墓を確認）。名は「歓楽の家」と訳され、ティムールの宴の伝説を生みましたが、建物は彼の死後のものです。ドームは1903年の地震で崩れましたが、建物の規模は今もよくわかります。",
    tr: "Şehrin güneydoğusunda 15. yüzyıldan görkemli kalıntılar. Türbeyi hükümdar Ebu Said'in eşi Habibe Sultan Begüm kızlarının mezarı üzerine yaptırdı; sonradan burada Timurlu kadınlar gömüldü — 1940 kazılarında mezarları bulundu. Adı “neşe evi” diye çevrilir ve Timur'un şölenleri hakkında bir efsaneye yol açmıştır, oysa yapı ondan sonra inşa edildi. Kubbe 1903 depreminde çöktü, ama yapının büyüklüğü hâlâ belli.",
    ar: "أطلال مهيبة من القرن الخامس عشر جنوب شرق المدينة. بنت الضريحَ حبيبة سلطان بيكم زوجةُ الحاكم أبي سعيد فوق قبر ابنتهما، ثم دُفنت فيه نساء من السلالة التيمورية، وقد عثرت حفريات 1940 على قبورهن. يُترجم الاسم بـ«بيت البهجة»، فنشأت أسطورة عن ولائم تيمور، مع أن المبنى شُيّد بعده. انهارت القبة في زلزال 1903، لكن ضخامة البناء ما زالت واضحة.",
  },
  smrukh: {
    en: "One of Samarkand's oldest mausoleums, built around 1380 under Amir Timur over the grave of the Sufi sheikh Burhaniddin Sagarji. The name means “abode of the spirit”. The building has no grand portal or bright tiles — a stern brick cube with a dome, in keeping with the sheikh's ascetic teaching. Legend says a casket with hairs of the Prophet is sealed in the dome. It stands next to Gur-e Amir.",
    uz: "Samarqandning eng qadimiy maqbaralaridan biri: u taxminan 1380 yilda Amir Temur davrida soʻfiy shayx Burhoniddin Sagʻarjiy qabri ustiga qurilgan. Nomi «ruh maskani» degan maʼnoni anglatadi. Binoning dabdabali peshtoqi ham, yorqin koshinlari ham yoʻq — shayxning zohidona taʼlimotiga mos sodda gʻishtin kub va gumbaz. Rivoyatga koʻra, gumbazga paygʻambarning sochlari solingan quticha joylangan. Goʻri Amir yonida joylashgan.",
    zh: "撒马尔罕最古老的陵墓之一，约1380年在帖木儿时期建于苏非派谢赫布尔哈尼丁·萨加尔吉的墓上。名称意为“灵魂居所”。建筑没有宏伟的门楼和鲜艳的瓷砖——一个带穹顶的朴素砖立方体，与谢赫的苦修教义相符。传说穹顶中封存着装有先知头发的匣子。它就在古尔-埃米尔旁边。",
    ko: "사마르칸트에서 가장 오래된 영묘 중 하나로, 1380년경 아미르 티무르 시대에 수피 셰이크 부르하니딘 사가르지의 묘 위에 지어졌습니다. 이름은 ‘영혼의 거처’라는 뜻입니다. 화려한 정문이나 밝은 타일 없이 돔을 얹은 소박한 벽돌 입방체로, 셰이크의 금욕적인 가르침과 닮았습니다. 전설에 따르면 돔 안에 예언자의 머리카락을 담은 상자가 봉인되어 있습니다. 구르에미르 바로 옆입니다.",
    de: "Eines der ältesten Mausoleen Samarkands, um 1380 unter Timur über dem Grab des Sufi-Scheichs Burhaniddin Sagardschi errichtet. Der Name bedeutet „Wohnstatt des Geistes“. Der Bau hat weder Prunkportal noch bunte Fliesen – ein strenger Ziegelkubus mit Kuppel, ganz im Geist der asketischen Lehre des Scheichs. Der Legende nach ist in der Kuppel ein Kästchen mit Haaren des Propheten eingemauert. Er steht neben Gur-Emir.",
    fr: "L'un des plus anciens mausolées de Samarcande, bâti vers 1380 sous Tamerlan sur la tombe du cheikh soufi Bourhaneddine Sagardji. Son nom signifie « demeure de l'esprit ». Ni portail d'apparat ni carreaux éclatants : un cube de brique austère coiffé d'une coupole, à l'image de l'enseignement ascétique du cheikh. Selon la légende, un coffret contenant des cheveux du Prophète est scellé dans la coupole. Il se trouve à côté du Gour-Emir.",
    ja: "サマルカンド最古級の霊廟の一つで、1380年頃ティムールの時代にスーフィーのシャイフ、ブルハニッディン・サガルジーの墓の上に建てられました。名は「魂の住まい」を意味します。壮麗な門も鮮やかなタイルもなく、ドームを載せた簡素なれんがの立方体は、シャイフの禁欲的な教えにふさわしい姿です。ドームには預言者の髪を収めた小箱が封じられているという伝説があります。グーリ・アミールのすぐ隣。",
    tr: "Semerkant'ın en eski türbelerinden biri; 1380 civarında Emir Timur döneminde sufi şeyh Burhaneddin Sagarci'nin mezarı üzerine yapıldı. Adı “ruhun meskeni” anlamına gelir. Görkemli bir taç kapısı ya da parlak çinileri yok — şeyhin zahidane öğretisine uygun, kubbeli sade bir tuğla küp. Rivayete göre kubbede Peygamber'in saçlarının bulunduğu bir kutu gömülüdür. Gur-i Emir'in hemen yanında.",
    ar: "من أقدم أضرحة سمرقند، بُني نحو عام 1380 في عهد الأمير تيمور فوق قبر الشيخ الصوفي برهان الدين الساغرجي. يعني اسمه «مقام الروح». لا بوابة فخمة فيه ولا بلاطات زاهية، بل مكعب من الطوب بسيط تعلوه قبة، على نهج تعاليم الشيخ الزاهدة. وتقول الأسطورة إن في القبة صندوقاً فيه شعرات من النبي. يقع بجوار غور أمير.",
  },
  smdani: {
    en: "A place revered by Muslims, Christians and Jews: tradition says Amir Timur brought the remains of the Prophet Daniel here from Susa. Inside is a tomb about 18 metres long, and the building is crowned by five domes. The mausoleum stands on a hill above the Siab stream, and at its foot a spring flows whose water is considered healing. Another version holds that Khoja Doniyor, a companion of Qusam ibn Abbas, is buried here.",
    uz: "Musulmonlar, nasroniylar va yahudiylar ulugʻlaydigan joy: rivoyatga koʻra, Amir Temur Daniyol paygʻambarning xokini Sus shahridan shu yerga keltirgan. Ichkarida uzunligi 18 metrcha boʻlgan qabr, binoning tepasida beshta gumbaz bor. Maqbara Siyob soyi ustidagi tepalikda turadi, etagida suvi shifobaxsh hisoblangan buloq oqadi. Boshqa bir rivoyatga koʻra, bu yerda Qusam ibn Abbosning safdoshi Xoʻja Doniyor dafn etilgan.",
    zh: "穆斯林、基督徒和犹太人共同尊崇之地：相传帖木儿将先知但以理的遗骸从苏萨迁到这里。陵内有一座长约18米的墓，建筑上方有五座穹顶。陵墓坐落在夏布河上方的山丘上，山脚涌出一眼泉水，被认为有疗效。另一种说法认为这里安葬的是库萨姆·伊本·阿拔斯的同伴霍贾·多尼约尔。",
    ko: "무슬림, 기독교인, 유대인 모두가 공경하는 곳입니다. 아미르 티무르가 예언자 다니엘의 유해를 수사에서 이곳으로 옮겼다고 전해집니다. 내부에는 길이 약 18미터의 묘가 있고 건물 위에는 다섯 개의 돔이 있습니다. 영묘는 시압 개울 위 언덕에 서 있으며, 기슭에서는 물이 병을 고친다고 여겨지는 샘이 솟습니다. 쿠삼 이븐 압바스의 동료 호자 도니요르가 묻혀 있다는 설도 있습니다.",
    de: "Ein Ort, den Muslime, Christen und Juden verehren: Der Überlieferung nach brachte Timur die Gebeine des Propheten Daniel aus Susa hierher. Im Inneren liegt ein etwa 18 Meter langes Grab, das Gebäude krönen fünf Kuppeln. Das Mausoleum steht auf einem Hügel über dem Bach Siab; an seinem Fuß entspringt eine Quelle, deren Wasser als heilkräftig gilt. Einer anderen Version nach liegt hier Chodscha Doniyor, ein Gefährte von Qusam ibn Abbas.",
    fr: "Un lieu vénéré par les musulmans, les chrétiens et les juifs : la tradition veut que Tamerlan y ait rapporté de Suse les restes du prophète Daniel. À l'intérieur, une tombe d'environ 18 mètres de long ; cinq coupoles couronnent l'édifice. Le mausolée domine le ruisseau Siab, et à son pied coule une source à l'eau réputée guérisseuse. Selon une autre version, c'est Khodja Doniyor, compagnon de Qusam ibn Abbas, qui repose ici.",
    ja: "イスラム教徒、キリスト教徒、ユダヤ教徒がともに崇める場所。ティムールが預言者ダニエルの遺骸をスーサから運んだと伝えられます。内部には長さ約18メートルの墓があり、建物には五つのドームが載ります。霊廟はシアブ川を見下ろす丘に建ち、麓には癒やしの水とされる泉が湧きます。クサム・イブン・アッバースの同志ホージャ・ドニヨルが眠るという別の説もあります。",
    tr: "Müslümanların, Hristiyanların ve Yahudilerin kutsal saydığı bir yer: rivayete göre Emir Timur, Peygamber Danyal'ın naaşını Sus'tan buraya getirtti. İçeride yaklaşık 18 metre uzunluğunda bir mezar vardır, binayı beş kubbe taçlandırır. Türbe Siyab deresine bakan bir tepede durur; eteğinde suyunun şifalı olduğuna inanılan bir kaynak akar. Başka bir rivayete göre burada Kusem bin Abbas'ın yoldaşı Hoca Doniyor yatar.",
    ar: "مكان يقدّسه المسلمون والمسيحيون واليهود: تقول الرواية إن الأمير تيمور نقل رفات النبي دانيال من سوسة إلى هنا. في داخله قبر طوله نحو 18 متراً، وتعلو المبنى خمس قباب. يقوم الضريح على تلة فوق جدول سياب، وعند سفحه نبع يُعتقد أن ماءه شافٍ. وفي رواية أخرى أن المدفون هنا هو خوجة دانيار، رفيق قُثم بن العباس.",
  },
  smkhizr: {
    en: "A mosque on a hill by Afrasiyab, where archaeologists say Samarkand's first mosque stood in the 8th century, and a Zoroastrian temple before it. The present building dates from 1854–1919; it has multicoloured tilework, unusual for the city, and a veranda with painted carved columns. From the hill you can see the Bibi-Khanym Mosque, the Siab Bazaar and Shah-i-Zinda. It is named after Khizr, the revered patron of travellers.",
    uz: "Afrosiyob yonidagi tepalikdagi masjid; arxeologlar maʼlumotiga koʻra, bu yerda VIII asrda Samarqandning ilk masjidi, undan oldin esa zardushtiylar ibodatxonasi boʻlgan. Hozirgi bino 1854–1919 yillarda qurilgan; uning shahar uchun noyob rang-barang bezagi va naqshinkor oʻymakor ustunli ayvoni bor. Tepalikdan Bibixonim masjidi, Siyob bozori va Shohi Zinda koʻrinadi. Masjid yoʻlovchilarning homiysi sanalgan Xizr nomi bilan atalgan.",
    zh: "阿夫拉西阿卜旁山丘上的清真寺，据考古学家称，8世纪撒马尔罕第一座清真寺就建在这里，更早之前是一座拜火教神庙。现存建筑建于1854–1919年，拥有城中少见的多彩饰面和带彩绘雕花木柱的回廊。从山上可以望见比比哈努姆清真寺、夏布集市和沙赫静达。清真寺以受人尊崇的旅人守护者希兹尔命名。",
    ko: "아프라시압 옆 언덕의 모스크로, 고고학자들에 따르면 8세기 사마르칸트 최초의 모스크가, 그 이전에는 조로아스터교 사원이 있던 자리입니다. 지금 건물은 1854~1919년에 지어졌으며 도시에서 보기 드문 다채로운 장식과 채색 조각 기둥이 있는 회랑이 특징입니다. 언덕에서 비비하눔 모스크, 시압 바자르, 샤히 진다가 보입니다. 여행자의 수호자로 공경받는 히즈르의 이름을 땄습니다.",
    de: "Eine Moschee auf einem Hügel bei Afrasiab, wo laut Archäologen im 8. Jahrhundert Samarkands erste Moschee stand und davor ein zoroastrischer Tempel. Der heutige Bau stammt von 1854–1919; er hat eine für die Stadt ungewöhnlich bunte Verkleidung und eine Veranda mit bemalten, geschnitzten Säulen. Vom Hügel sieht man die Bibi-Chanum-Moschee, den Siab-Basar und Schah-i-Sinda. Benannt ist sie nach Chisr, dem verehrten Schutzpatron der Reisenden.",
    fr: "Une mosquée sur une colline près d'Afrasiab, là où, selon les archéologues, s'élevait au VIIIe siècle la première mosquée de Samarcande, et avant elle un temple zoroastrien. L'édifice actuel date de 1854–1919 ; il arbore un décor multicolore rare dans la ville et une véranda aux colonnes sculptées et peintes. De la colline, on voit la mosquée Bibi-Khanoum, le bazar Siab et Chah-i-Zinda. Elle porte le nom de Khizr, patron vénéré des voyageurs.",
    ja: "アフラシアブそばの丘に建つモスク。考古学者によれば、ここには8世紀にサマルカンド最初のモスクが、その前にはゾロアスター教の神殿がありました。現在の建物は1854〜1919年のもので、市内では珍しい多色の装飾と、彩色彫刻の柱が並ぶアイヴァンが特徴。丘からビビ・ハヌム・モスク、シアブ・バザール、シャーヒ・ズィンダが見渡せます。旅人の守護者として敬われるヒズルにちなむ名です。",
    tr: "Afrasiyab yakınında bir tepedeki cami; arkeologlara göre burada 8. yüzyılda Semerkant'ın ilk camisi, ondan önce de bir Zerdüşt tapınağı vardı. Bugünkü yapı 1854–1919 tarihli; şehirde ender görülen rengârenk süslemesi ve boyalı oymalı sütunlu bir eyvanı var. Tepeden Bibi Hanım Camii, Siyab Pazarı ve Şah-ı Zinde görünür. Adını yolcuların koruyucusu sayılan Hızır'dan alır.",
    ar: "مسجد على تلة قرب أفراسياب، حيث يقول علماء الآثار إن أول مسجد في سمرقند قام في القرن الثامن، وقبله معبد زرادشتي. يعود المبنى الحالي إلى 1854–1919، وفيه كسوة متعددة الألوان نادرة في المدينة وإيوان بأعمدة منحوتة ملوّنة. من التلة ترى مسجد بيبي خانم وسوق سياب وشاه زنده. سُمّي باسم الخضر، الحامي المبجّل للمسافرين.",
  },
  smkarim: {
    en: "The memorial of Islam Karimov (1938–2016), the first president of independent Uzbekistan, next to the Hazrat Khizr Mosque. The mausoleum is built in traditional style — a dome, carved stone and ornament — and fits the historic look of the hill. It is a place of remembrance: people speak quietly and dress modestly here.",
    uz: "Mustaqil Oʻzbekistonning birinchi Prezidenti Islom Karimov (1938–2016) xotira majmuasi, Hazrati Xizr masjidi yonida. Maqbara anʼanaviy uslubda — gumbaz, oʻymakor tosh va naqshlar bilan qurilgan va tepalikning tarixiy qiyofasiga uygʻun. Bu xotira joyi: bu yerda ohista gapiriladi va odobli kiyiniladi.",
    zh: "独立后的乌兹别克斯坦首任总统伊斯兰·卡里莫夫（1938–2016）的纪念建筑群，位于哈兹拉特·希兹尔清真寺旁。陵墓采用传统风格——穹顶、石雕和纹饰——与山丘的历史风貌相融。这是缅怀之地：请轻声交谈、着装得体。",
    ko: "독립 우즈베키스탄의 초대 대통령 이슬람 카리모프(1938~2016)의 기념 단지로, 하즈라트 히즈르 모스크 옆에 있습니다. 영묘는 돔, 조각 석재, 문양 등 전통 양식으로 지어져 언덕의 역사적 경관과 어우러집니다. 추모의 장소이니 조용히 말하고 단정하게 입으세요.",
    de: "Die Gedenkstätte für Islam Karimow (1938–2016), den ersten Präsidenten des unabhängigen Usbekistan, neben der Hazrat-Chisr-Moschee. Das Mausoleum ist im traditionellen Stil gebaut – Kuppel, behauener Stein, Ornamente – und fügt sich in das historische Bild des Hügels. Es ist ein Ort des Gedenkens: Man spricht leise und kleidet sich dezent.",
    fr: "Le mémorial d'Islam Karimov (1938–2016), premier président de l'Ouzbékistan indépendant, à côté de la mosquée Hazrat Khizr. Le mausolée, de style traditionnel — coupole, pierre sculptée, ornements —, s'intègre à l'aspect historique de la colline. C'est un lieu de mémoire : on y parle bas et on s'habille sobrement.",
    ja: "独立ウズベキスタンの初代大統領イスラム・カリモフ（1938〜2016年）の記念施設で、ハズラト・ヒズル・モスクの隣にあります。霊廟はドーム、彫刻を施した石、文様という伝統様式で建てられ、丘の歴史的な景観に溶け込んでいます。追悼の場なので、静かに、控えめな服装で。",
    tr: "Bağımsız Özbekistan'ın ilk cumhurbaşkanı İslam Kerimov'un (1938–2016) anıt mezarı, Hazreti Hızır Camii'nin yanında. Türbe geleneksel üslupta — kubbe, oyma taş ve süslemelerle — yapılmış ve tepenin tarihî görünümüne uyum sağlar. Burası bir anma yeri: alçak sesle konuşulur ve sade giyinilir.",
    ar: "النصب التذكاري لإسلام كريموف (1938–2016)، أول رئيس لأوزبكستان المستقلة، بجوار مسجد حضرة الخضر. بُني الضريح على الطراز التقليدي — قبة وحجر منحوت وزخارف — منسجماً مع الطابع التاريخي للتلة. إنه مكان للذكرى: يتحدث الناس فيه بهدوء ويرتدون ملابس محتشمة.",
  },
  smmuz: {
    en: "One of the oldest museums in Central Asia: founded in Samarkand in 1896, it holds tens of thousands of objects. Here you'll find archaeology from the Bronze Age to the Middle Ages, ossuaries, ceramics, textiles and carpets, about 30,000 coins and an art gallery with works by Vereshchagin, Karazin and Usto Mumin. The museum is part of the Samarkand State Museum-Reserve.",
    uz: "Markaziy Osiyodagi eng qadimiy muzeylardan biri: u 1896 yilda Samarqandda tashkil etilgan, fondlarida oʻn minglab buyumlar bor. Bu yerda bronza davridan oʻrta asrlargacha boʻlgan arxeologiya, ossuariylar, sopol buyumlar, matolar va gilamlar, 30 mingga yaqin tanga hamda Vereshchagin, Karazin va Usto Moʻmin asarlari jamlangan rasmlar galereyasi bor. Muzey Samarqand davlat muzey-qoʻriqxonasi tarkibiga kiradi.",
    zh: "中亚最古老的博物馆之一：1896年创建于撒马尔罕，藏品数以万计。这里有从青铜时代到中世纪的考古文物、骨瓮、陶器、织物和地毯、约3万枚钱币，以及收藏韦列夏金、卡拉津和乌斯托·穆明作品的美术馆。博物馆隶属撒马尔罕国家博物馆保护区。",
    ko: "중앙아시아에서 가장 오래된 박물관 중 하나로 1896년 사마르칸트에서 설립되었으며 소장품이 수만 점에 이릅니다. 청동기부터 중세까지의 고고학 유물, 납골함, 도자기, 직물과 카펫, 약 3만 점의 동전, 베레샤긴·카라진·우스토 무민의 작품이 있는 미술관을 볼 수 있습니다. 사마르칸트 국립 박물관 보호구역에 속합니다.",
    de: "Eines der ältesten Museen Zentralasiens: 1896 in Samarkand gegründet, mit Zehntausenden Objekten. Zu sehen sind Archäologie von der Bronzezeit bis zum Mittelalter, Ossuarien, Keramik, Textilien und Teppiche, rund 30.000 Münzen und eine Gemäldegalerie mit Werken von Wereschtschagin, Karasin und Usto Mumin. Das Museum gehört zum Staatlichen Museumsreservat Samarkand.",
    fr: "L'un des plus anciens musées d'Asie centrale : fondé à Samarcande en 1896, il conserve des dizaines de milliers d'objets. On y voit l'archéologie de l'âge du bronze au Moyen Âge, des ossuaires, des céramiques, des textiles et des tapis, environ 30 000 monnaies et une galerie de peinture avec des œuvres de Verechtchaguine, Karazine et Ousto Moumine. Il fait partie du musée-réserve d'État de Samarcande.",
    ja: "中央アジア最古級の博物館で、1896年にサマルカンドで創設され、所蔵品は数万点にのぼります。青銅器時代から中世までの考古資料、納骨器、陶器、織物や絨毯、約3万枚の硬貨、ヴェレシチャーギン、カラジン、ウスト・ムミンの作品を収めた絵画館があります。サマルカンド国立博物館保護区の一部です。",
    tr: "Orta Asya'nın en eski müzelerinden biri: 1896'da Semerkant'ta kuruldu, koleksiyonunda on binlerce eser var. Tunç Çağı'ndan Orta Çağ'a arkeoloji, osuarlar, seramikler, dokumalar ve halılar, yaklaşık 30.000 sikke ve Vereşçagin, Karazin ve Usto Mumin'in eserlerinin bulunduğu bir resim galerisi görebilirsiniz. Müze, Semerkant Devlet Müze-Koruma Alanı'na bağlıdır.",
    ar: "من أقدم متاحف آسيا الوسطى: تأسس في سمرقند عام 1896 ويضم عشرات الآلاف من القطع. تجد فيه آثاراً من العصر البرونزي إلى العصور الوسطى، ونواويس وخزفاً ومنسوجات وسجاداً، ونحو 30 ألف قطعة نقدية، ومعرضاً للوحات فيرشاغين وكارازين وأوستو مؤمن. المتحف جزء من محمية سمرقند الحكومية للمتاحف.",
  },
  smkray: {
    en: "A museum in an early-20th-century mansion that the architect E. O. Nelle built for the merchant Abram Kalantarov, a leader of the Bukharan Jewish community. The interiors are an exhibit in themselves: carved painted ceilings, ganch plasterwork, stained glass, tiled stoves. The displays cover the region's history from the Stone Age, everyday life and crafts, and there is a nature section with landscapes of the Zarafshan valley.",
    uz: "Arxitektor Ye. O. Nelle buxoro yahudiylari jamoasi yetakchilaridan biri — savdogar Abram Kalantarov uchun qurgan XX asr boshidagi qasrdagi muzey. Ichki bezaklarning oʻzi koʻrgazma: oʻymakor naqshli shiftlar, ganch, vitrajlar, koshinli pechlar. Ekspozitsiya oʻlka tarixi haqida tosh davridan boshlab, turmush va hunarmandchilik haqida hikoya qiladi; Zarafshon vodiysi landshaftlari aks etgan tabiat boʻlimi ham bor.",
    zh: "博物馆位于一座20世纪初的宅邸中，由建筑师E. O. 内列为布哈拉犹太社区领袖之一、商人阿布拉姆·卡兰塔罗夫所建。室内本身就是展品：彩绘雕花天花板、石膏雕饰、彩色玻璃、瓷砖火炉。展览讲述从石器时代起的地方历史、生活与手工艺，还有展示泽拉夫尚河谷景观的自然展区。",
    ko: "건축가 E. O. 넬레가 부하라 유대인 공동체 지도자인 상인 아브람 칼란타로프를 위해 지은 20세기 초 저택에 있는 박물관입니다. 조각과 채색 천장, 간치 석고 장식, 스테인드글라스, 타일 난로 등 실내 자체가 전시품입니다. 석기 시대부터의 지역 역사, 생활과 공예를 다루며 제라프샨 계곡의 풍경을 보여 주는 자연 전시관도 있습니다.",
    de: "Ein Museum in einer Villa vom Anfang des 20. Jahrhunderts, die der Architekt E. O. Nelle für den Kaufmann Abram Kalantarow baute, einen der Führer der bucharisch-jüdischen Gemeinde. Die Innenräume sind selbst ein Exponat: geschnitzte, bemalte Decken, Gantsch-Stuck, Buntglasfenster, gekachelte Öfen. Die Ausstellung zeigt die Geschichte der Region seit der Steinzeit, Alltag und Handwerk; dazu eine Naturabteilung mit Landschaften des Serafschan-Tals.",
    fr: "Un musée installé dans une demeure du début du XXe siècle que l'architecte E. O. Nelle bâtit pour le marchand Abram Kalantarov, l'un des chefs de la communauté juive boukhariote. Les intérieurs sont une exposition à eux seuls : plafonds sculptés et peints, stucs de gantch, vitraux, poêles en faïence. Les collections retracent l'histoire de la région depuis l'âge de pierre, la vie quotidienne et l'artisanat ; une section nature présente les paysages de la vallée du Zeravchan.",
    ja: "建築家E・O・ネッレがブハラ・ユダヤ人共同体の指導者の一人、商人アブラム・カランタロフのために建てた20世紀初頭の邸宅にある博物館。彫刻と彩色の天井、ガンチ（漆喰）細工、ステンドグラス、タイル張りのストーブなど、内装そのものが見どころです。石器時代からの地域の歴史、暮らしと工芸を紹介し、ザラフシャン渓谷の風景を再現した自然展示もあります。",
    tr: "Mimar E. O. Nelle'nin, Buhara Yahudi topluluğunun önderlerinden tüccar Abram Kalantarov için yaptığı 20. yüzyıl başı bir konakta müze. İç mekânlar başlı başına bir sergi: oymalı boyalı tavanlar, ganç işçiliği, vitraylar, çinili sobalar. Sergi, bölgenin Taş Devri'nden bu yana tarihini, gündelik yaşamı ve zanaatları anlatır; Zerefşan vadisinin manzaralarını gösteren bir doğa bölümü de var.",
    ar: "متحف في قصر من أوائل القرن العشرين بناه المعماري إ. أ. نيلّه للتاجر أبرام كالانتاروف، أحد قادة الجالية اليهودية البخارية. التصميم الداخلي معرض بحد ذاته: أسقف منحوتة ملوّنة وزخارف جصية «غانتش» وزجاج معشّق ومدافئ مكسوّة بالبلاط. يعرض المتحف تاريخ المنطقة منذ العصر الحجري والحياة اليومية والحرف، وفيه قسم للطبيعة بمناظر وادي زرافشان.",
  },
  smbehb: {
    en: "The museum of the enlightener Mahmudkhoja Behbudi (1875–1919) — a journalist, playwright and one of the leaders of the Jadids, the reformers of education in Turkestan. His play “The Patricide” is considered the first Uzbek drama. The exhibits include documents, photographs and publications about the Jadids, the new schools and the first local press.",
    uz: "Maʼrifatparvar Mahmudxoʻja Behbudiy (1875–1919) muzeyi — publitsist, dramaturg va Turkistonda taʼlimni isloh qilgan jadidlarning yetakchilaridan biri. Uning «Padarkush» pyesasi birinchi oʻzbek dramasi hisoblanadi. Ekspozitsiyada jadidlar, yangi usul maktablari va ilk mahalliy matbuot haqidagi hujjatlar, fotosuratlar va nashrlar bor.",
    zh: "启蒙思想家马赫穆德霍贾·贝赫布迪（1875–1919）的纪念馆。他是政论家、剧作家，也是突厥斯坦教育改革者“扎吉德”运动的领袖之一。他的剧作《弑父》被视为第一部乌兹别克戏剧。展品包括有关扎吉德运动、新式学校和最早地方报刊的文件、照片和出版物。",
    ko: "계몽가 마흐무드호자 베흐부디(1875~1919)의 박물관입니다. 그는 언론인이자 극작가였으며 투르키스탄 교육 개혁가인 자디드 운동의 지도자 중 한 명이었습니다. 그의 희곡 『아버지 살해자』는 최초의 우즈베크 희곡으로 여겨집니다. 자디드, 신식 학교, 최초의 지역 언론에 관한 문서와 사진, 출판물이 전시되어 있습니다.",
    de: "Das Museum des Aufklärers Mahmudchodscha Behbudi (1875–1919) – Publizist, Dramatiker und einer der Anführer der Dschadiden, der Bildungsreformer Turkestans. Sein Stück „Der Vatermörder“ gilt als erstes usbekisches Drama. Gezeigt werden Dokumente, Fotografien und Schriften über die Dschadiden, die neuen Schulen und die erste einheimische Presse.",
    fr: "Le musée de l'éclaireur Mahmoudkhodja Behbudi (1875–1919), journaliste, dramaturge et l'un des chefs des djadids, réformateurs de l'enseignement au Turkestan. Sa pièce « Le Parricide » passe pour le premier drame ouzbek. On y voit documents, photographies et publications sur les djadids, les écoles nouvelles et la première presse locale.",
    ja: "啓蒙家マフムードホジャ・ベフブーディー（1875〜1919年）の記念館。ジャーナリスト、劇作家であり、トルキスタンの教育改革者ジャディードの指導者の一人でした。戯曲『父殺し』は最初のウズベク劇とされています。ジャディード運動、新方式学校、最初の地元出版に関する文書、写真、刊行物を展示しています。",
    tr: "Aydınlanmacı Mahmudhoca Behbudi'nin (1875–1919) müzesi — gazeteci, oyun yazarı ve Türkistan'da eğitimi yenileyen Ceditçilerin önderlerinden biri. “Babakatili” adlı oyunu ilk Özbek draması sayılır. Ceditçiler, yeni usul okullar ve ilk yerel basın hakkında belgeler, fotoğraflar ve yayınlar sergilenir.",
    ar: "متحف المصلح محمود خوجة بهبودي (1875–1919)، الصحفي والكاتب المسرحي وأحد قادة الجديديين، مصلحي التعليم في تركستان. تُعدّ مسرحيته «قاتل أبيه» أول مسرحية أوزبكية. يعرض المتحف وثائق وصوراً ومطبوعات عن الجديديين والمدارس الحديثة وأولى الصحف المحلية.",
  },
  smayni: {
    en: "The house where Sadriddin Ayni — writer and scholar, a classic of Tajik literature who also wrote in Uzbek — lived and worked from 1923 to 1954. The museum opened in 1967: his study, living rooms and belongings are preserved, and other rooms cover his books and the Samarkand of his time. It is on Registan Street, a few minutes from the square.",
    uz: "Tojik adabiyotining klassigi, oʻzbek tilida ham ijod qilgan yozuvchi va olim Sadriddin Ayniy 1923–1954 yillarda yashab ijod qilgan uy. Muzey 1967 yilda ochilgan: yozuvchining ish xonasi, yashash xonalari va buyumlari saqlangan, uning kitoblari va oʻsha davrdagi Samarqand haqidagi zallar ham bor. Registon koʻchasida, maydondan bir necha daqiqalik yoʻlda.",
    zh: "作家、学者萨德里丁·艾尼于1923年至1954年在此生活和工作，他是塔吉克文学的经典作家，也用乌兹别克语写作。博物馆于1967年开放：保留了他的书房、起居室和遗物，另有展厅介绍他的作品和他那个时代的撒马尔罕。位于雷吉斯坦街，离广场仅几分钟。",
    ko: "타지크 문학의 고전 작가이자 우즈베크어로도 글을 쓴 작가·학자 사드리딘 아이니가 1923~1954년 살며 일한 집입니다. 1967년 박물관으로 문을 열었으며 서재, 거실, 유품이 보존되어 있고 그의 작품과 당시 사마르칸트를 다룬 전시실도 있습니다. 레기스탄 거리에 있어 광장에서 몇 분 거리입니다.",
    de: "Das Haus, in dem Sadriddin Aini – Schriftsteller und Gelehrter, Klassiker der tadschikischen Literatur, der auch auf Usbekisch schrieb – von 1923 bis 1954 lebte und arbeitete. Das Museum wurde 1967 eröffnet: Arbeitszimmer, Wohnräume und persönliche Dinge sind erhalten; weitere Räume zeigen seine Bücher und das Samarkand seiner Zeit. Es liegt an der Registan-Straße, wenige Minuten vom Platz.",
    fr: "La maison où vécut et travailla de 1923 à 1954 Sadriddine Aïni, écrivain et savant, classique de la littérature tadjike qui écrivit aussi en ouzbek. Le musée a ouvert en 1967 : son bureau, ses pièces à vivre et ses objets sont conservés, et d'autres salles évoquent ses livres et la Samarcande de son temps. Il se trouve rue du Registan, à quelques minutes de la place.",
    ja: "タジク文学の古典的作家で、ウズベク語でも執筆した作家・学者サドリッディン・アイニーが1923〜1954年に暮らし仕事をした家。1967年に博物館として開館し、書斎、居間、遺品が保存され、作品や当時のサマルカンドを紹介する部屋もあります。レギスタン通りにあり、広場から数分です。",
    tr: "Tacik edebiyatının klasiği olan, Özbekçe de yazan yazar ve bilgin Sadreddin Ayni'nin 1923–1954 yılları arasında yaşayıp çalıştığı ev. Müze 1967'de açıldı: çalışma odası, yaşam odaları ve eşyaları korunmuştur; ayrıca kitaplarını ve yaşadığı dönemin Semerkant'ını anlatan salonlar var. Registan Caddesi'nde, meydana birkaç dakika uzaklıkta.",
    ar: "البيت الذي عاش فيه وعمل من 1923 إلى 1954 صدر الدين عيني، الكاتب والعالم، أحد كلاسيكيي الأدب الطاجيكي الذي كتب بالأوزبكية أيضاً. افتُتح المتحف عام 1967: حُفظ فيه مكتبه وغرف معيشته وأغراضه، وفيه قاعات عن كتبه وعن سمرقند في زمنه. يقع في شارع ريجستان على بعد دقائق من الساحة.",
  },
  smabdu: {
    en: "The memorial museum of the Samarkand singer and musician Hoji Abdulaziz Abdurasulov, a master of the classical shashmaqom music. It opened in 2020 in the Kokmachit neighbourhood, close to the Registan, and holds photographs, documents and the story of Samarkand's musical traditions.",
    uz: "Samarqandlik xonanda va sozanda, shashmaqom mumtoz musiqasi ustasi Hoji Abdulaziz Abdurasulovning xotira muzeyi. Muzey 2020 yilda Registon yaqinidagi Koʻkmachit mahallasida ochilgan; unda fotosuratlar, hujjatlar va Samarqandning musiqiy anʼanalari haqida hikoya jamlangan.",
    zh: "撒马尔罕歌唱家、音乐家霍吉·阿卜杜拉齐兹·阿卜杜拉苏洛夫的纪念馆，他是古典音乐“沙什木卡姆”的大师。博物馆于2020年在雷吉斯坦附近的科克马奇特街区开放，展出照片、文件，讲述撒马尔罕的音乐传统。",
    ko: "고전 음악 샤슈마콤의 거장인 사마르칸트의 가수이자 음악가 호지 압둘아지즈 압두라술로프의 기념 박물관입니다. 2020년 레기스탄 근처 코크마치트 마할라에 문을 열었으며 사진과 문서, 사마르칸트 음악 전통 이야기를 담고 있습니다.",
    de: "Das Gedenkmuseum des Samarkander Sängers und Musikers Hodschi Abdulasis Abdurasulow, eines Meisters der klassischen Schaschmaqom-Musik. Es wurde 2020 im Viertel Kokmatschit nahe dem Registan eröffnet und zeigt Fotos, Dokumente und die Musiktraditionen Samarkands.",
    fr: "Le musée-mémorial du chanteur et musicien samarcandais Hodji Abdoulaziz Abdourassoulov, maître de la musique classique shashmaqom. Ouvert en 2020 dans le quartier de Kokmatchit, près du Registan, il présente photographies, documents et l'histoire des traditions musicales de Samarcande.",
    ja: "古典音楽シャシュマカームの名手、サマルカンドの歌手・音楽家ホージ・アブドゥラジズ・アブドゥラスロフの記念館。2020年にレギスタン近くのコクマチト地区で開館し、写真や文書、サマルカンドの音楽伝統を紹介しています。",
    tr: "Klasik şeşmakam müziğinin ustası Semerkantlı şarkıcı ve müzisyen Hoca Abdülaziz Abdurasulov'un anma müzesi. 2020'de Registan yakınındaki Kökmaçit mahallesinde açıldı; fotoğraflar, belgeler ve Semerkant'ın müzik geleneklerini anlatan bir sergi içerir.",
    ar: "المتحف التذكاري للمغني والموسيقي السمرقندي حاجي عبد العزيز عبد الرسولوف، أحد أساتذة موسيقى «الشش مقام» الكلاسيكية. افتُتح عام 2020 في حي كوكماتشيت قرب ريجستان، ويضم صوراً ووثائق وحكاية التقاليد الموسيقية في سمرقند.",
  },
  smabdi: {
    en: "An ensemble in the south-east of Samarkand at the grave of Khoja Abdi Darun, a revered 9th-century theologian. Over time the mausoleum was surrounded by a mosque, a khanqah and a courtyard with a pool under old trees; people come here to pray and to rest in the shade. Don't confuse it with the Khoja Ahrar ensemble — they are different places. The Ishratkhona ruins are nearby.",
    uz: "Samarqandning janubi-sharqida, IX asrda yashagan ulugʻ ilohiyotchi Xoʻja Abdi Darun qabri yonidagi ansambl. Vaqt oʻtishi bilan maqbara atrofida masjid, xonaqoh va keksa daraxtlar soyasidagi hovuzli hovli paydo boʻlgan; bu yerga ibodat qilish va soyada dam olish uchun kelishadi. Uni Xoʻja Ahror ansambli bilan adashtirmang — bular boshqa-boshqa joylar. Yaqinida Ishratxona xarobalari bor.",
    zh: "撒马尔罕东南部的建筑群，位于受尊崇的9世纪神学家霍贾·阿卜迪·达伦墓旁。随着时间推移，陵墓周围建起了清真寺、修道院以及古树下带水池的庭院；人们来此礼拜，也在树荫下休憩。不要与霍贾·阿赫拉尔建筑群混淆——它们是不同的地方。附近就是伊什拉特霍纳遗迹。",
    ko: "사마르칸트 남동쪽, 존경받는 9세기 신학자 호자 압디 다룬의 묘 옆에 있는 앙상블입니다. 시간이 흐르며 영묘 주위에 모스크와 수도원, 오래된 나무 아래 연못이 있는 안뜰이 생겼고, 사람들은 기도하고 그늘에서 쉬러 옵니다. 호자 아흐라르 앙상블과 혼동하지 마세요. 서로 다른 곳입니다. 근처에 이쉬라트호나 유적이 있습니다.",
    de: "Ein Ensemble im Südosten Samarkands am Grab von Chodscha Abdi Darun, einem verehrten Theologen des 9. Jahrhunderts. Mit der Zeit kamen zum Mausoleum eine Moschee, eine Chanaka und ein Hof mit Wasserbecken unter alten Bäumen hinzu; man kommt zum Beten und zum Ausruhen im Schatten. Nicht mit dem Ensemble Chodscha Ahrar verwechseln – das sind verschiedene Orte. Die Ruinen von Ischratchona liegen in der Nähe.",
    fr: "Un ensemble au sud-est de Samarcande, sur la tombe de Khodja Abdi Daroun, théologien vénéré du IXe siècle. Au fil du temps, le mausolée s'est entouré d'une mosquée, d'une khanqah et d'une cour avec bassin sous de vieux arbres ; on y vient prier et se reposer à l'ombre. À ne pas confondre avec l'ensemble de Khodja Ahrar : ce sont deux lieux différents. Les ruines d'Ichratkhona sont tout près.",
    ja: "サマルカンド南東、崇敬される9世紀の神学者ホージャ・アブディ・ダルンの墓に建つ建築群。時とともに霊廟の周りにモスク、ハーンカー、古木の下に池のある中庭が加わり、人々は祈りに、また木陰で休みに訪れます。ホージャ・アフラール建築群とは別の場所なので混同しないように。近くにイシュラトホナの廃墟があります。",
    tr: "Semerkant'ın güneydoğusunda, 9. yüzyılın saygın ilahiyatçısı Hoca Abdi Darun'un mezarı başında bir külliye. Zamanla türbenin çevresine bir cami, bir hankah ve yaşlı ağaçların altında havuzlu bir avlu eklendi; insanlar buraya dua etmeye ve gölgede dinlenmeye gelir. Hoca Ahrar Külliyesi ile karıştırmayın — farklı yerlerdir. Yakında İşrethane kalıntıları var.",
    ar: "مجمع جنوب شرق سمرقند عند قبر خوجة عبدي دارون، العالم الديني المبجّل من القرن التاسع. مع الزمن أحاط بالضريح مسجد وخانقاه وفناء فيه حوض ماء تحت أشجار معمّرة، ويأتي الناس للصلاة والاستراحة في الظل. لا تخلط بينه وبين مجمع خوجة أحرار، فهما مكانان مختلفان. وبالقرب منه أطلال عشرت خانه.",
  },
  smmatu: {
    en: "The memorial of the theologian Abu Mansur al-Maturidi (died around 944), founder of the Maturidi school of Islamic creed, followed from Central Asia to Turkey. He is buried in Samarkand's old Chokardiza cemetery, where a modern mausoleum stands over the grave. It is a quiet place, near the old Jewish quarter.",
    uz: "Markaziy Osiyodan Turkiyagacha keng tarqalgan moturidiya aqidaviy maktabining asoschisi, ilohiyotchi Abu Mansur al-Moturidiy (taxminan 944 yilda vafot etgan) xotira maskani. U Samarqandning eski Chokardiza qabristonida dafn etilgan, qabri ustida zamonaviy maqbara turibdi. Joy sokin, yaqinida eski yahudiylar mahallasi bor.",
    zh: "神学家阿布·曼苏尔·马图里迪（约944年去世）的纪念地，他是马图里迪教义学派的创始人，该学派从中亚流传到土耳其。他葬于撒马尔罕古老的乔卡尔迪扎墓地，墓上建有现代陵墓。这里十分安静，附近是古老的犹太街区。",
    ko: "중앙아시아에서 튀르키예까지 널리 퍼진 마투리디 신학파의 창시자 아부 만수르 알마투리디(944년경 사망)를 기리는 곳입니다. 그는 사마르칸트의 오래된 초카르디자 묘지에 묻혔고 묘 위에는 현대식 영묘가 서 있습니다. 조용한 곳이며 근처에 옛 유대인 지구가 있습니다.",
    de: "Die Gedenkstätte des Theologen Abu Mansur al-Maturidi († um 944), des Begründers der maturiditischen Schule der islamischen Glaubenslehre, die von Zentralasien bis in die Türkei verbreitet ist. Er ruht auf dem alten Samarkander Friedhof Tschokardisa, über dem Grab steht ein modernes Mausoleum. Ein stiller Ort nahe dem alten jüdischen Viertel.",
    fr: "Le mémorial du théologien Abou Mansour al-Maturidi (mort vers 944), fondateur de l'école maturidite de la foi islamique, suivie de l'Asie centrale à la Turquie. Il repose dans le vieux cimetière de Tchokardiza à Samarcande, où un mausolée moderne surmonte sa tombe. Un lieu paisible, près de l'ancien quartier juif.",
    ja: "中央アジアからトルコまで広がるマートゥリーディー学派の創始者、神学者アブー・マンスール・マートゥリーディー（944年頃没）の記念地。サマルカンドの古いチョカルディザ墓地に葬られ、墓の上に現代の霊廟が建っています。静かな場所で、近くに旧ユダヤ人地区があります。",
    tr: "Orta Asya'dan Türkiye'ye kadar yayılan Mâtürîdî itikat ekolünün kurucusu ilahiyatçı Ebu Mansur el-Mâtürîdî'nin (ö. y. 944) anma yeri. Semerkant'ın eski Çakerdize mezarlığında gömülüdür; mezarının üzerinde modern bir türbe yükselir. Sakin bir yer, eski Yahudi mahallesine yakın.",
    ar: "مقام العالم أبي منصور الماتريدي (توفي نحو 944)، مؤسس المدرسة الماتريدية في العقيدة الإسلامية المنتشرة من آسيا الوسطى إلى تركيا. دُفن في مقبرة جاكرديزه القديمة في سمرقند، ويقوم فوق قبره ضريح حديث. مكان هادئ قرب الحي اليهودي القديم.",
  },
  smtemur: {
    en: "A bronze Amir Timur on a throne at the start of University Boulevard, near Gur-e Amir. The monument was unveiled in 1996 for the 660th anniversary of the ruler under whom Samarkand became the capital of a vast empire. A popular photo spot, especially in the evening.",
    uz: "Universitet xiyobonining boshida, Goʻri Amir yaqinida taxtda oʻtirgan bronza Amir Temur haykali. Haykal 1996 yilda Samarqandni ulkan saltanat poytaxtiga aylantirgan hukmdor tavalludining 660 yilligiga bagʻishlab oʻrnatilgan. Ayniqsa kechqurun suratga tushish uchun sevimli joy.",
    zh: "大学林荫大道起点、古尔-埃米尔附近的帖木儿青铜坐像。纪念像于1996年为纪念这位统治者诞辰660周年而落成，正是在他的统治下撒马尔罕成为庞大帝国的首都。这里是热门的拍照地点，傍晚尤佳。",
    ko: "구르에미르 근처 대학교 대로 시작점에 있는, 왕좌에 앉은 아미르 티무르 청동상입니다. 사마르칸트를 거대한 제국의 수도로 만든 그의 탄생 660주년을 맞아 1996년에 세워졌습니다. 특히 저녁에 사진 찍기 좋은 인기 장소입니다.",
    de: "Ein bronzener Amir Timur auf dem Thron am Anfang des Universitätsboulevards, nahe Gur-Emir. Das Denkmal wurde 1996 zum 660. Geburtstag des Herrschers enthüllt, unter dem Samarkand Hauptstadt eines riesigen Reiches wurde. Ein beliebtes Fotomotiv, besonders am Abend.",
    fr: "Un Amir Timour de bronze sur son trône, au début du boulevard de l'Université, près du Gour-Emir. Le monument a été inauguré en 1996 pour le 660e anniversaire du souverain qui fit de Samarcande la capitale d'un immense empire. Un spot photo très prisé, surtout le soir.",
    ja: "グーリ・アミール近く、大学通りの起点に立つ玉座のアミール・ティムールのブロンズ像。サマルカンドを大帝国の都とした君主の生誕660年を記念し、1996年に建てられました。特に夕方は人気の撮影スポットです。",
    tr: "Gur-i Emir yakınında, Üniversite Bulvarı'nın başında tahtta oturan bronz bir Emir Timur. Anıt, Semerkant'ı büyük bir imparatorluğun başkenti yapan hükümdarın doğumunun 660. yıldönümü için 1996'da açıldı. Özellikle akşamları sevilen bir fotoğraf noktası.",
    ar: "تمثال برونزي للأمير تيمور جالساً على عرشه عند بداية شارع الجامعة قرب غور أمير. أُزيح الستار عنه عام 1996 في الذكرى الـ660 لميلاد الحاكم الذي جعل سمرقند عاصمة إمبراطورية واسعة. مكان محبوب للتصوير، خاصة في المساء.",
  },
  smbulv: {
    en: "A green boulevard in the “new” part of Samarkand laid out in the late 19th century: old plane trees, the university building and mansions of that era. It begins at the Amir Timur monument, and the Registan is about 15 minutes away on foot. A lovely place for an unhurried evening stroll.",
    uz: "Samarqandning XIX asr oxirida barpo etilgan «yangi» qismidagi yashil xiyobon: keksa chinorlar, universitet binosi va oʻsha davr qasrlari. U Amir Temur haykalidan boshlanadi, bu yerdan Registongacha piyoda 15 daqiqacha. Kechki sokin sayr uchun ajoyib joy.",
    zh: "撒马尔罕“新城”中的绿色林荫大道，建于19世纪末：古老的悬铃木、大学主楼和那个年代的宅邸。大道从帖木儿纪念像开始，步行到雷吉斯坦约15分钟。适合傍晚悠闲散步。",
    ko: "19세기 말에 조성된 사마르칸트 ‘신시가지’의 녹색 대로로, 오래된 플라타너스와 대학 건물, 그 시대의 저택들이 늘어서 있습니다. 아미르 티무르 기념상에서 시작하며 레기스탄까지 걸어서 약 15분입니다. 여유로운 저녁 산책에 좋은 곳입니다.",
    de: "Ein grüner Boulevard im Ende des 19. Jahrhunderts angelegten „neuen“ Teil Samarkands: alte Platanen, das Universitätsgebäude und Villen jener Zeit. Er beginnt am Amir-Timur-Denkmal; bis zum Registan sind es zu Fuß etwa 15 Minuten. Schön für einen gemütlichen Abendspaziergang.",
    fr: "Un boulevard verdoyant dans la « nouvelle » Samarcande tracée à la fin du XIXe siècle : vieux platanes, bâtiment de l'université et demeures de l'époque. Il commence au monument d'Amir Timour ; le Registan est à environ 15 minutes à pied. Idéal pour une promenade tranquille en soirée.",
    ja: "19世紀末に造られたサマルカンドの「新市街」を通る緑の並木道。古いプラタナス、大学の建物、当時の邸宅が並びます。アミール・ティムール像から始まり、レギスタンまでは徒歩約15分。夕方のゆったりした散歩にぴったりです。",
    tr: "Semerkant'ın 19. yüzyıl sonunda kurulan “yeni” kesimindeki yeşil bulvar: yaşlı çınarlar, üniversite binası ve o dönemin konakları. Emir Timur Anıtı'ndan başlar; Registan'a yürüyerek yaklaşık 15 dakika. Akşam saatlerinde sakin bir yürüyüş için harika.",
    ar: "شارع أخضر في الجزء «الجديد» من سمرقند الذي خُطّط في أواخر القرن التاسع عشر: أشجار دلب معمّرة ومبنى الجامعة وقصور من تلك الحقبة. يبدأ عند نصب الأمير تيمور، ويبعد ريجستان نحو 15 دقيقة سيراً. مكان جميل لنزهة مسائية هادئة.",
  },
  smchrs: {
    en: "The old Chorsu trading dome right behind the Sher-Dor Madrasa — hats were once sold here. Today the round hall under the dome is a gallery of paintings, drawings, ceramics and embroidery by artists from Samarkand and elsewhere in Uzbekistan, with exhibitions and workshops. Drop in straight after the Registan — it is a two-minute walk.",
    uz: "Sherdor madrasasining ortidagi qadimiy «Chorsu» savdo gumbazi — bir vaqtlar bu yerda bosh kiyimlar sotilgan. Bugun gumbaz ostidagi doira shaklidagi zalda Samarqand va Oʻzbekistonning boshqa hududlaridan kelgan ijodkorlarning rangtasvir, grafika, sopol va kashtachilik asarlari galereyasi joylashgan, koʻrgazma va mahorat darslari oʻtkaziladi. Registondan keyin darhol kiring — ikki qadam masofada.",
    zh: "希尔多尔经学院正后方的古老乔尔苏商业穹顶——这里曾经出售帽子。如今穹顶下的圆形大厅是一座画廊，展出撒马尔罕及乌兹别克斯坦其他地区艺术家的绘画、版画、陶瓷和刺绣，并举办展览和工作坊。看完雷吉斯坦顺道进来，只有几步路。",
    ko: "셰르도르 마드라사 바로 뒤에 있는 옛 초르수 상업 돔으로, 예전엔 모자를 팔던 곳입니다. 지금은 돔 아래 원형 홀이 사마르칸트와 우즈베키스탄 각지 작가들의 회화, 그래픽, 도자기, 자수를 전시하는 갤러리로, 전시회와 워크숍이 열립니다. 레기스탄을 본 뒤 바로 들르세요. 몇 걸음 거리입니다.",
    de: "Die alte Handelskuppel Chorsu direkt hinter der Scher-Dor-Medrese – früher wurden hier Kopfbedeckungen verkauft. Heute ist der runde Saal unter der Kuppel eine Galerie mit Malerei, Grafik, Keramik und Stickerei von Künstlern aus Samarkand und anderen Teilen Usbekistans; es gibt Ausstellungen und Workshops. Gleich nach dem Registan vorbeischauen – nur ein paar Schritte.",
    fr: "La vieille coupole marchande de Tchorsou, juste derrière la médersa Cher-Dor — on y vendait autrefois des chapeaux. Aujourd'hui, la salle ronde sous la coupole est une galerie : peinture, dessin, céramique et broderie d'artistes de Samarcande et d'ailleurs en Ouzbékistan, avec expositions et ateliers. Passez-y juste après le Registan, c'est à deux pas.",
    ja: "シェルドル・メドレセのすぐ裏にある古い交易ドーム「チョルスー」。かつては帽子が売られていました。現在はドームの下の円形ホールがギャラリーとなり、サマルカンドやウズベキスタン各地の作家による絵画、版画、陶芸、刺繍を展示し、展覧会やワークショップも開かれます。レギスタンのあとにすぐ寄れる距離です。",
    tr: "Şirdar Medresesi'nin hemen arkasındaki eski Çorsu ticaret kubbesi — bir zamanlar burada başlık satılırdı. Bugün kubbenin altındaki yuvarlak salon, Semerkant'tan ve Özbekistan'ın diğer bölgelerinden sanatçıların resim, grafik, seramik ve nakış eserlerinin sergilendiği bir galeri; sergiler ve atölyeler düzenlenir. Registan'dan hemen sonra uğrayın, iki adım ötede.",
    ar: "قبة تشورسو التجارية القديمة خلف مدرسة شير دور مباشرة، حيث كانت تُباع القبعات قديماً. واليوم صارت القاعة المستديرة تحت القبة معرضاً للوحات والرسوم والخزف والتطريز لفنانين من سمرقند ومن أنحاء أوزبكستان، تُقام فيه معارض وورش عمل. ادخله بعد ريجستان مباشرة، فهو على بعد خطوتين.",
  },
  smhudj: {
    en: "A workshop where silk and wool carpets are woven by hand to old patterns; the weavers spend months on a single carpet. You can watch cocoons being unwound, threads dyed with natural dyes and knots tied, and choose a carpet or suzani in the showroom. It is best to arrange a tour of the workshop in advance.",
    uz: "Qadimiy naqshlar asosida qoʻlda ipak va jun gilamlar toʻqiladigan ustaxona; toʻquvchilar bitta gilam ustida oylab ishlaydi. Pillani yechish, iplarni tabiiy boʻyoqlar bilan boʻyash va tugun bogʻlashni tomosha qilish, shourumda esa gilam yoki soʻzana tanlash mumkin. Ustaxonaga ekskursiyani oldindan kelishib olgan maʼqul.",
    zh: "按古老图案手工编织丝绸和羊毛地毯的作坊，织工们织一张地毯要花几个月。你可以看到缫丝、用天然染料染线和打结的过程，还能在展厅挑选地毯或苏扎尼刺绣。参观作坊最好提前预约。",
    ko: "옛 문양대로 실크와 양모 카펫을 손으로 짜는 공방으로, 직공들은 카펫 한 장에 몇 달을 들입니다. 누에고치에서 실을 푸는 과정, 천연 염료로 실을 물들이고 매듭을 짓는 과정을 볼 수 있고, 쇼룸에서 카펫이나 수자니를 고를 수 있습니다. 공방 견학은 미리 예약하는 것이 좋습니다.",
    de: "Eine Werkstatt, in der Seiden- und Wollteppiche nach alten Mustern von Hand geknüpft werden; an einem Teppich arbeiten die Weberinnen monatelang. Man sieht, wie Kokons abgewickelt, Fäden mit Naturfarben gefärbt und Knoten geknüpft werden, und kann im Showroom einen Teppich oder ein Susani aussuchen. Eine Führung vorab vereinbaren.",
    fr: "Un atelier où l'on tisse à la main des tapis de soie et de laine selon des motifs anciens ; les tisserandes passent des mois sur un seul tapis. On voit dévider les cocons, teindre les fils aux colorants naturels et nouer les points, puis on choisit un tapis ou un suzani dans la salle d'exposition. Mieux vaut réserver la visite à l'avance.",
    ja: "伝統文様に従って絹と羊毛の絨毯を手織りする工房。一枚の絨毯に織り手は何か月もかけます。繭から糸を繰る工程、天然染料で糸を染め結び目を作る様子を見学でき、ショールームで絨毯やスザニを選べます。工房見学は事前の予約がおすすめ。",
    tr: "Eski desenlere göre elde ipek ve yün halıların dokunduğu bir atölye; dokumacılar tek bir halı üzerinde aylarca çalışır. Kozaların çözülmesini, ipliklerin doğal boyalarla boyanmasını ve düğümlerin atılmasını izleyebilir, sergi salonunda bir halı ya da suzani seçebilirsiniz. Atölye turunu önceden ayarlamak en iyisi.",
    ar: "ورشة يُنسج فيها السجاد الحريري والصوفي يدوياً على نقوش قديمة، وتقضي النساجات شهوراً على السجادة الواحدة. يمكنك مشاهدة حلّ شرانق الحرير وصباغة الخيوط بأصباغ طبيعية وعقد العُقد، واختيار سجادة أو «سوزاني» في صالة العرض. يُستحسن الترتيب للجولة في الورشة مسبقاً.",
  },
  smwine: {
    en: "A museum at Samarkand's oldest winery, founded by the merchant Dmitry Filatov in 1868; the winery later took the name of the winemaker Mikhail Khovrenko, who created well-known wines here. The exhibits include old tools, labels, medals and bottles from Filatov's secret cache found in 1967. After the visit there is a tasting — adults only.",
    uz: "1868 yilda savdogar Dmitriy Filatov asos solgan Samarqanddagi eng qadimiy vino zavodi qoshidagi muzey; keyinroq zavodga bu yerda mashhur vino navlarini yaratgan vinochi Mixail Xovrenko nomi berilgan. Ekspozitsiyada eski asboblar, yorliqlar, medallar va 1967 yilda topilgan Filatovning yashirin omboridagi shishalar bor. Koʻrikdan soʻng degustatsiya oʻtkaziladi — faqat voyaga yetganlar uchun.",
    zh: "位于撒马尔罕最古老的葡萄酒厂内的博物馆，酒厂由商人德米特里·菲拉托夫于1868年创立，后以在此酿出名酒的酿酒师米哈伊尔·霍夫连科命名。展品包括旧工具、酒标、奖章，以及1967年发现的菲拉托夫秘密酒窖中的酒瓶。参观后有品酒环节——仅限成年人。",
    ko: "상인 드미트리 필라토프가 1868년에 세운 사마르칸트에서 가장 오래된 와이너리의 박물관입니다. 이후 이곳에서 유명한 와인을 만든 양조가 미하일 호브렌코의 이름을 따게 되었습니다. 옛 도구, 라벨, 메달, 1967년에 발견된 필라토프의 비밀 저장고 병들이 전시되어 있습니다. 관람 후 시음이 있으며 성인만 가능합니다.",
    de: "Ein Museum in Samarkands ältester Weinkellerei, 1868 vom Kaufmann Dmitri Filatow gegründet; später erhielt sie den Namen des Winzers Michail Chowrenko, der hier bekannte Weine schuf. Zu sehen sind alte Werkzeuge, Etiketten, Medaillen und Flaschen aus Filatows 1967 entdecktem Geheimlager. Danach gibt es eine Verkostung – nur für Erwachsene.",
    fr: "Un musée dans la plus ancienne cave de Samarcande, fondée par le marchand Dmitri Filatov en 1868 ; elle prit ensuite le nom du vinificateur Mikhaïl Khovrenko, créateur de vins réputés. On y voit d'anciens outils, des étiquettes, des médailles et des bouteilles de la cachette secrète de Filatov découverte en 1967. La visite se termine par une dégustation, réservée aux adultes.",
    ja: "1868年に商人ドミトリー・フィラトフが創業したサマルカンド最古のワイナリーにある博物館。のちに、ここで名高いワインを生んだ醸造家ミハイル・ホブレンコの名が付けられました。古い道具、ラベル、メダル、1967年に見つかったフィラトフの隠し蔵のボトルを展示。見学後に試飲があります（成人のみ）。",
    tr: "Tüccar Dmitriy Filatov'un 1868'de kurduğu Semerkant'ın en eski şarap fabrikasındaki müze; fabrika daha sonra burada ünlü şaraplar yaratan şarap ustası Mihail Hovrenko'nun adını aldı. Eski aletler, etiketler, madalyalar ve 1967'de bulunan Filatov'un gizli mahzeninden şişeler sergilenir. Ziyaretten sonra tadım yapılır — yalnızca yetişkinler için.",
    ar: "متحف في أقدم مصنع للنبيذ في سمرقند، أسسه التاجر ديمتري فيلاتوف عام 1868، ثم حمل اسم صانع النبيذ ميخائيل خوفرينكو الذي ابتكر فيه أنواعاً مشهورة. يعرض أدوات قديمة وملصقات وميداليات وزجاجات من مخبأ فيلاتوف السري الذي اكتُشف عام 1967. تُختتم الزيارة بتذوق للبالغين فقط.",
  },
  smsilk: {
    en: "A modern tourist complex in the east of Samarkand, opened in 2022: hotels, a congress hall, canals and promenades. Inside is the “Eternal City”, which recreates the lanes, workshops and teahouses of old Samarkand with craftspeople and evening shows. It is not a historic monument but a place to stroll and relax, especially in the evening.",
    uz: "Samarqandning sharqidagi 2022 yilda ochilgan zamonaviy turistik majmua: mehmonxonalar, kongress-zal, kanallar va sayr qilish uchun sohillar. Ichida «Boqiy shahar» bor — unda hunarmandlar va kechki tomoshalar bilan eski Samarqandning tor koʻchalari, ustaxonalari va choyxonalari qayta yaratilgan. Bu tarixiy yodgorlik emas, balki ayniqsa kechqurun sayr va dam olish uchun joy.",
    zh: "撒马尔罕东部的现代旅游综合体，2022年开放：酒店、会议厅、运河和滨水步道。园内有“永恒之城”，重现了老撒马尔罕的街巷、作坊和茶馆，有手工艺人和夜间表演。这里不是历史古迹，而是散步休闲的好去处，傍晚尤佳。",
    ko: "2022년에 문을 연 사마르칸트 동쪽의 현대식 관광 단지로, 호텔, 컨벤션 홀, 운하와 산책로가 있습니다. 안에는 장인과 저녁 공연이 함께하는, 옛 사마르칸트의 골목과 공방, 찻집을 재현한 ‘영원의 도시’가 있습니다. 역사 유적이 아니라 특히 저녁에 산책하고 쉬기 좋은 곳입니다.",
    de: "Ein moderner Tourismuskomplex im Osten Samarkands, 2022 eröffnet: Hotels, Kongresshalle, Kanäle und Promenaden. Darin liegt die „Ewige Stadt“, die Gassen, Werkstätten und Teehäuser des alten Samarkand mit Handwerkern und Abendshows nachbildet. Kein historisches Denkmal, sondern ein Ort zum Flanieren und Entspannen, besonders am Abend.",
    fr: "Un complexe touristique moderne à l'est de Samarcande, ouvert en 2022 : hôtels, palais des congrès, canaux et promenades. À l'intérieur, la « Ville éternelle » recrée ruelles, ateliers et maisons de thé du vieux Samarcande, avec artisans et spectacles du soir. Ce n'est pas un monument historique, mais un lieu de promenade et de détente, surtout le soir.",
    ja: "2022年に開業したサマルカンド東部の近代的な観光複合施設。ホテル、コングレスホール、運河、遊歩道があります。中には職人や夜のショーとともに旧市街の路地、工房、チャイハナを再現した「永遠の街」があります。史跡ではなく、特に夕方に散策してくつろぐための場所です。",
    tr: "Semerkant'ın doğusunda 2022'de açılan modern bir turizm kompleksi: oteller, kongre salonu, kanallar ve gezinti yolları. İçinde zanaatkârlar ve akşam gösterileriyle eski Semerkant'ın sokaklarını, atölyelerini ve çayhanelerini yeniden canlandıran “Ebedî Şehir” bulunur. Tarihî bir anıt değil, özellikle akşamları gezip dinlenmek için bir yer.",
    ar: "مجمع سياحي حديث شرق سمرقند افتُتح عام 2022: فنادق وقاعة مؤتمرات وقنوات وممشيات. وفي داخله «المدينة الخالدة» التي تعيد بناء أزقة سمرقند القديمة وورشها ومقاهيها مع الحرفيين وعروض المساء. ليس معلماً تاريخياً، بل مكان للتنزه والاسترخاء، خاصة في المساء.",
  },
  smbukh: {
    en: "A memorial complex in the village of Hartang, 25 km north of Samarkand, over the grave of Imam Muhammad al-Bukhari (810–870), compiler of the “Sahih”, the most authoritative hadith collection for Sunni Muslims. The complex was built in 1998 and recently expanded: a mausoleum, a large mosque and museum pavilions. One of the main pilgrimage sites in Uzbekistan — allow half a day including the drive.",
    uz: "Samarqanddan 25 km shimoldagi Xartang qishlogʻidagi, sunniy musulmonlar uchun eng nufuzli hadislar toʻplami «Sahih»ning muallifi imom Muhammad al-Buxoriy (810–870) qabri ustidagi yodgorlik majmuasi. Majmua 1998 yilda barpo etilgan va yaqinda kengaytirilgan: maqbara, katta masjid va muzey pavilonlari. Oʻzbekistondagi asosiy ziyoratgohlardan biri — yoʻl bilan birga yarim kun ajrating.",
    zh: "位于撒马尔罕以北25公里哈尔唐村的纪念建筑群，建在伊玛目穆罕默德·布哈里（810–870）墓上。他编纂的《布哈里圣训实录》是逊尼派穆斯林最权威的圣训集。建筑群建于1998年，近年扩建，包括陵墓、大清真寺和博物馆展馆。这是乌兹别克斯坦最重要的朝圣地之一——连同车程请预留半天。",
    ko: "사마르칸트에서 북쪽으로 25km 떨어진 하르탕 마을의 기념 단지로, 수니파 무슬림에게 가장 권위 있는 하디스 모음집 『사히흐』의 편찬자 이맘 무함마드 알부하리(810~870)의 묘 위에 세워졌습니다. 1998년에 건립되고 최근 확장되어 영묘, 대형 모스크, 박물관 전시관이 있습니다. 우즈베키스탄의 주요 순례지 중 하나로, 이동 시간을 포함해 반나절을 잡으세요.",
    de: "Ein Gedenkkomplex im Dorf Hartang, 25 km nördlich von Samarkand, über dem Grab des Imam Muhammad al-Buchari (810–870), des Verfassers des „Sahih“, der für sunnitische Muslime maßgeblichsten Hadith-Sammlung. Der Komplex entstand 1998 und wurde kürzlich erweitert: Mausoleum, große Moschee und Museumspavillons. Einer der wichtigsten Wallfahrtsorte Usbekistans – mit Anfahrt einen halben Tag einplanen.",
    fr: "Un complexe mémorial au village de Khartang, à 25 km au nord de Samarcande, sur la tombe de l'imam Muhammad al-Boukhari (810–870), compilateur du « Sahih », le recueil de hadiths le plus respecté des musulmans sunnites. Construit en 1998 et récemment agrandi, il réunit un mausolée, une grande mosquée et des pavillons de musée. L'un des principaux lieux de pèlerinage d'Ouzbékistan : comptez une demi-journée avec le trajet.",
    ja: "サマルカンドの北25km、ハルタング村にある記念施設で、スンナ派イスラム教徒にとって最も権威あるハディース集『サヒーフ』の編者イマーム・ムハンマド・ブハーリー（810〜870年）の墓の上に建っています。1998年に建てられ、近年拡張されて霊廟、大モスク、博物館パビリオンがあります。ウズベキスタン有数の巡礼地。移動を含め半日見ておきましょう。",
    tr: "Semerkant'ın 25 km kuzeyindeki Hartang köyünde, Sünni Müslümanlar için en muteber hadis derlemesi “Sahih”in derleyicisi İmam Muhammed el-Buhari'nin (810–870) mezarı üzerinde bir anıt külliye. 1998'de yapıldı ve yakın zamanda genişletildi: türbe, büyük bir cami ve müze pavyonları. Özbekistan'ın başlıca ziyaret yerlerinden biri — yol dahil yarım gün ayırın.",
    ar: "مجمع تذكاري في قرية خرتنك على بعد 25 كم شمال سمرقند، فوق قبر الإمام محمد البخاري (810–870)، جامع «الصحيح» أوثق كتب الحديث عند أهل السنة. بُني المجمع عام 1998 ووُسّع مؤخراً: ضريح ومسجد كبير وأجنحة متحفية. من أهم أماكن الزيارة في أوزبكستان، فخصّص نصف يوم مع الطريق.",
  },
  smmakh: {
    en: "A pilgrimage site in the town of Dahbed, about 15 km north of Samarkand, at the grave of Makhdumi Azam, a 16th-century Sufi sheikh of the Naqshbandi order. The ensemble includes a mausoleum, a mosque and a shady courtyard; the mosque is associated with the ruler Yalangtush Biy and the year 1619.",
    uz: "Samarqanddan taxminan 15 km shimoldagi Dahbed shaharchasida, Naqshbandiya tariqatining XVI asrda yashagan soʻfiy shayxi Mahdumi Aʼzam qabri yonidagi ziyoratgoh. Ansamblga maqbara, masjid va soyali hovli kiradi; masjid qurilishi hukmdor Yalangtoʻsh biy nomi va 1619 yil bilan bogʻlanadi.",
    zh: "位于撒马尔罕以北约15公里的达赫别德镇的朝圣地，在纳克什班迪教团16世纪苏非派谢赫马赫杜米·阿扎姆的墓旁。建筑群包括陵墓、清真寺和绿荫庭院；清真寺的修建与统治者亚兰图什·比伊和1619年相关。",
    ko: "사마르칸트에서 북쪽으로 약 15km 떨어진 다흐베드 마을의 순례지로, 낙쉬반디 교단의 16세기 수피 셰이크 마흐두미 아잠의 묘가 있습니다. 영묘, 모스크, 그늘진 안뜰로 이루어져 있으며 모스크는 통치자 얄랑투시 비이와 1619년과 연관됩니다.",
    de: "Ein Wallfahrtsort in der Ortschaft Dahbed, etwa 15 km nördlich von Samarkand, am Grab von Machdumi Asam, einem Sufi-Scheich des Naqschbandi-Ordens aus dem 16. Jahrhundert. Zum Ensemble gehören Mausoleum, Moschee und ein schattiger Hof; die Moschee wird mit dem Herrscher Jalangtusch Bij und dem Jahr 1619 verbunden.",
    fr: "Un lieu de pèlerinage dans la bourgade de Dakhbed, à environ 15 km au nord de Samarcande, sur la tombe de Makhdoumi Azam, cheikh soufi naqshbandi du XVIe siècle. L'ensemble comprend un mausolée, une mosquée et une cour ombragée ; la mosquée est associée au souverain Yalangtouch Biy et à l'année 1619.",
    ja: "サマルカンドの北約15km、ダフベドの町にある巡礼地で、ナクシュバンディー教団の16世紀のスーフィー、マフドゥーミ・アーザムの墓があります。霊廟、モスク、木陰の中庭からなり、モスクは君主ヤラングトゥシュ・ビーと1619年に結び付けられています。",
    tr: "Semerkant'ın yaklaşık 15 km kuzeyindeki Dahbed kasabasında, Nakşibendi tarikatının 16. yüzyıl sufi şeyhi Mahdum-i Azam'ın mezarı başında bir ziyaret yeri. Külliyede türbe, cami ve gölgeli bir avlu bulunur; caminin yapımı hükümdar Yalangtuş Biy ve 1619 yılıyla ilişkilendirilir.",
    ar: "مكان زيارة في بلدة دهبيد على بعد نحو 15 كم شمال سمرقند، عند قبر مخدومي أعظم، الشيخ الصوفي النقشبندي من القرن السادس عشر. يضم المجمع ضريحاً ومسجداً وفناءً ظليلاً، ويُنسب بناء المسجد إلى الحاكم يلنكتوش بيّ وعام 1619.",
  },
  smdaud: {
    en: "A holy place in the mountains about 40 km south-west of Samarkand, reached by a long stone staircase. Legend says the Prophet Daud (David) prayed here and left the prints of his palms in the rock. The climb takes about an hour, with mountain views at the top. Bring comfortable shoes and water; in summer it is best to climb early in the morning.",
    uz: "Samarqanddan taxminan 40 km janubi-gʻarbdagi togʻlardagi muqaddas joy: gʻorga uzun tosh zinapoya olib boradi. Rivoyatga koʻra, bu yerda Dovud paygʻambar ibodat qilgan va toshda uning kaftlari izi qolgan. Koʻtarilish bir soatcha davom etadi, tepadan togʻlar manzarasi ochiladi. Qulay oyoq kiyim va suv oling; yozda erta tongda chiqqan maʼqul.",
    zh: "撒马尔罕西南约40公里山中的圣地，一段长长的石阶通往洞穴。传说先知达伍德（大卫）曾在此祈祷，岩石上留下了他的掌印。攀登约需一小时，山顶可眺望群山。请穿舒适的鞋并带水；夏季最好清晨上山。",
    ko: "사마르칸트에서 남서쪽으로 약 40km 떨어진 산속의 성지로, 긴 돌계단이 동굴로 이어집니다. 전설에 따르면 예언자 다우드(다윗)가 이곳에서 기도했고 바위에 손바닥 자국이 남았습니다. 오르는 데 약 1시간이 걸리며 정상에서 산의 풍경이 펼쳐집니다. 편한 신발과 물을 챙기고, 여름엔 이른 아침에 오르는 것이 좋습니다.",
    de: "Ein heiliger Ort in den Bergen etwa 40 km südwestlich von Samarkand, zu dem eine lange Steintreppe führt. Der Legende nach betete hier der Prophet Daud (David) und hinterließ Abdrücke seiner Handflächen im Fels. Der Aufstieg dauert etwa eine Stunde, oben gibt es Bergblicke. Bequeme Schuhe und Wasser mitnehmen; im Sommer am besten früh morgens aufsteigen.",
    fr: "Un lieu saint dans les montagnes, à environ 40 km au sud-ouest de Samarcande, auquel mène un long escalier de pierre. La légende dit que le prophète Daoud (David) y pria et laissa l'empreinte de ses paumes dans la roche. La montée prend environ une heure, avec vue sur les montagnes au sommet. Prévoyez de bonnes chaussures et de l'eau ; l'été, montez de préférence tôt le matin.",
    ja: "サマルカンドの南西約40kmの山中にある聖地で、長い石段が洞窟へ続きます。伝説では預言者ダウード（ダビデ）がここで祈り、岩に手のひらの跡を残したといいます。登りは約1時間、頂上からは山々の眺め。歩きやすい靴と水を忘れずに。夏は早朝に登るのがおすすめ。",
    tr: "Semerkant'ın yaklaşık 40 km güneybatısında, dağlarda kutsal bir yer; mağaraya uzun bir taş merdiven çıkar. Rivayete göre Peygamber Davud burada dua etmiş ve kayada avuçlarının izi kalmıştır. Tırmanış yaklaşık bir saat sürer, tepeden dağ manzarası görülür. Rahat ayakkabı ve su alın; yazın sabah erken çıkmak en iyisi.",
    ar: "مكان مقدس في الجبال على بعد نحو 40 كم جنوب غرب سمرقند، يصل إليه درج حجري طويل. تقول الأسطورة إن النبي داود صلّى هنا وترك آثار كفّيه في الصخر. يستغرق الصعود نحو ساعة، ومن القمة إطلالة على الجبال. احمل حذاءً مريحاً وماءً، ويُفضَّل الصعود صباحاً باكراً في الصيف.",
  },
  smchor: {
    en: "A shady garden in Urgut at the foot of the mountains: huge plane trees (chinar), said to be several centuries old, surround a pond fed by a spring. Nearby is a mosque begun in the early 20th century. Locals come here to rest and pray; the trip combines well with the Urgut bazaar.",
    uz: "Urgutda togʻ etagidagi soyali bogʻ: bir necha asrlik deb hisoblanadigan ulkan chinorlar buloq suvi bilan toʻladigan hovuzni oʻrab turadi. Yonida XX asr boshida qurila boshlangan masjid bor. Mahalliy aholi bu yerga dam olish va ibodat qilish uchun keladi; sayohatni Urgut bozori bilan qoʻshish qulay.",
    zh: "乌尔古特山脚下一座绿荫浓密的花园：据说树龄已有数百年的巨大悬铃木环绕着泉水汇成的池塘。附近有一座始建于20世纪初的清真寺。当地人来此休憩和礼拜；行程可以与乌尔古特集市结合。",
    ko: "우르구트 산기슭의 그늘진 정원으로, 수백 년 되었다는 거대한 플라타너스(치나르)가 샘물이 고인 연못을 둘러싸고 있습니다. 근처에 20세기 초에 짓기 시작한 모스크가 있습니다. 현지인들이 쉬고 기도하러 오는 곳이며, 우르구트 바자르와 함께 둘러보기 좋습니다.",
    de: "Ein schattiger Garten in Urgut am Fuß der Berge: riesige Platanen (Tschinar), denen ein Alter von mehreren Jahrhunderten nachgesagt wird, umstehen einen quellgespeisten Teich. Nebenan steht eine Anfang des 20. Jahrhunderts begonnene Moschee. Einheimische kommen zum Ausruhen und Beten; gut mit dem Basar von Urgut zu verbinden.",
    fr: "Un jardin ombragé à Ourgout, au pied des montagnes : d'immenses platanes (tchinars), réputés vieux de plusieurs siècles, entourent un bassin alimenté par une source. À côté, une mosquée commencée au début du XXe siècle. Les habitants viennent s'y reposer et prier ; à combiner avec le bazar d'Ourgout.",
    ja: "ウルグトの山麓にある木陰の庭園。樹齢数百年といわれる巨大なプラタナス（チナル）が、泉の湧く池を囲んでいます。近くには20世紀初めに建て始められたモスクがあります。地元の人が休み、祈りに訪れる場所で、ウルグトのバザールと組み合わせると便利です。",
    tr: "Urgut'ta dağların eteğinde gölgeli bir bahçe: birkaç yüzyıllık olduğu söylenen dev çınarlar, bir kaynaktan beslenen havuzu çevreler. Yanında 20. yüzyıl başında yapımına başlanan bir cami var. Yerel halk buraya dinlenmeye ve dua etmeye gelir; gezi Urgut pazarıyla birleştirilebilir.",
    ar: "حديقة ظليلة في أورغوت عند سفح الجبال: أشجار دلب (چنار) ضخمة يُقال إن عمرها قرون تحيط ببركة يغذّيها نبع. وبجوارها مسجد بدأ بناؤه في أوائل القرن العشرين. يأتي إليها السكان للراحة والصلاة، ويمكن الجمع بينها وبين سوق أورغوت.",
  },
  smdabu: {
    en: "The remains of a medieval town and fortress in the Zarafshan valley, in the west of Samarkand Region on the road to Bukhara. High earthen mounds of the citadel and traces of fortifications survive. It is an undeveloped archaeological site rather than a museum: bring sturdy shoes and water, and check the access road in advance.",
    uz: "Zarafshon vodiysidagi, Samarqand viloyatining gʻarbida Buxoro yoʻlidagi oʻrta asr shahri va qalʼasi qoldiqlari. Arkning baland tuproq tepaliklari va mudofaa inshootlari izlari saqlanib qolgan. Bu muzey emas, obodonlashtirilmagan arxeologik maydon: mustahkam oyoq kiyim va suv oling, yoʻlni oldindan aniqlang.",
    zh: "泽拉夫尚河谷中世纪城镇和要塞的遗迹，位于撒马尔罕州西部通往布哈拉的路上。城堡高耸的土丘和防御工事的痕迹保存至今。这是一处未经开发的考古遗址而非博物馆：请穿结实的鞋、带水，并提前确认道路。",
    ko: "부하라로 가는 길, 사마르칸트주 서쪽 제라프샨 계곡에 있는 중세 도시와 요새의 유적입니다. 성채의 높은 흙 언덕과 방어 시설의 흔적이 남아 있습니다. 박물관이 아닌 정비되지 않은 고고학 현장이므로 튼튼한 신발과 물을 챙기고 진입로를 미리 확인하세요.",
    de: "Reste einer mittelalterlichen Stadt und Festung im Serafschan-Tal, im Westen des Gebiets Samarkand an der Straße nach Buchara. Erhalten sind hohe Erdhügel der Zitadelle und Spuren der Befestigungen. Eine unerschlossene Ausgrabungsstätte, kein Museum: feste Schuhe und Wasser mitnehmen, die Zufahrt vorher klären.",
    fr: "Les vestiges d'une ville et d'une forteresse médiévales dans la vallée du Zeravchan, à l'ouest de la région de Samarcande, sur la route de Boukhara. Subsistent les hautes buttes de terre de la citadelle et des traces de fortifications. C'est un site archéologique non aménagé, pas un musée : prévoyez de bonnes chaussures, de l'eau, et renseignez-vous sur l'accès.",
    ja: "サマルカンド州西部、ブハラへ向かう道沿いのザラフシャン渓谷にある中世の町と要塞の遺跡。城塞の高い土塁と防備の跡が残ります。博物館ではなく未整備の考古遺跡なので、丈夫な靴と水を用意し、アクセス路を事前に確認してください。",
    tr: "Zerefşan vadisinde, Semerkant bölgesinin batısında Buhara yolu üzerinde bir Orta Çağ kasabası ve kalesinin kalıntıları. İç kalenin yüksek toprak tepeleri ve surların izleri günümüze ulaşmıştır. Burası müze değil, düzenlenmemiş bir arkeolojik alan: sağlam ayakkabı ve su alın, yolu önceden öğrenin.",
    ar: "بقايا مدينة وقلعة من العصور الوسطى في وادي زرافشان، غربي ولاية سمرقند على طريق بخارى. بقيت تلال ترابية عالية للقلعة وآثار للتحصينات. إنه موقع أثري غير مجهّز وليس متحفاً: احمل حذاءً متيناً وماءً، وتحقّق من طريق الوصول مسبقاً.",
  },
  smravt: {
    en: "An old bridge near the village of Ravatkhodja in Urgut District, on one of the ancient routes across the Zarafshan valley. People come for the historic engineering, the river and the rural scenery. The bridge's condition changes over time — do not walk onto closed or unsafe sections.",
    uz: "Urgut tumanidagi Ravotxoʻja qishlogʻi yaqinidagi, Zarafshon vodiysi orqali oʻtgan qadimiy yoʻllardan biridagi eski koʻprik. Bu yerga muhandislik yodgorligi, daryo va qishloq manzaralari uchun kelishadi. Koʻprikning holati vaqt oʻtishi bilan oʻzgaradi — yopiq va xavfli qismlarga chiqmang.",
    zh: "乌尔古特区拉瓦特霍贾村附近的一座古桥，位于穿越泽拉夫尚河谷的古道之一。人们来这里欣赏古老的工程、河流和乡村风光。桥体状况会随时间变化——请勿走上封闭或危险的区段。",
    ko: "우르구트 지역 라바트호자 마을 근처, 제라프샨 계곡을 가로지르던 옛길 중 하나에 있는 오래된 다리입니다. 옛 공학 유산과 강, 시골 풍경을 보러 옵니다. 다리 상태는 시간이 지나며 달라지니 폐쇄되었거나 위험한 구간에는 올라가지 마세요.",
    de: "Eine alte Brücke beim Dorf Rawatchodscha im Bezirk Urgut, an einem der alten Wege durch das Serafschan-Tal. Man kommt wegen der historischen Ingenieurkunst, des Flusses und der ländlichen Landschaft. Der Zustand der Brücke ändert sich – gesperrte oder unsichere Abschnitte nicht betreten.",
    fr: "Un vieux pont près du village de Ravatkhodja, dans le district d'Ourgout, sur l'une des anciennes routes traversant la vallée du Zeravchan. On y vient pour l'ouvrage ancien, la rivière et les paysages ruraux. L'état du pont évolue : ne vous aventurez pas sur les parties fermées ou dangereuses.",
    ja: "ウルグト地区ラヴァトホジャ村の近く、ザラフシャン渓谷を渡る古い道の一つにある古橋。歴史的な土木遺産、川、田園風景を目当てに訪れます。橋の状態は年々変わるので、閉鎖・危険な区間には立ち入らないでください。",
    tr: "Urgut ilçesindeki Ravathoca köyü yakınında, Zerefşan vadisini geçen eski yollardan biri üzerinde eski bir köprü. Tarihî mühendislik, nehir ve kırsal manzara için gelinir. Köprünün durumu zamanla değişir — kapalı ya da tehlikeli bölümlere çıkmayın.",
    ar: "جسر قديم قرب قرية رباط خوجة في مقاطعة أورغوت، على أحد الطرق القديمة عبر وادي زرافشان. يأتيه الناس لهندسته التاريخية والنهر والمناظر الريفية. تتغير حالة الجسر مع الزمن، فلا تسِر على الأجزاء المغلقة أو غير الآمنة.",
  },
};
